--
-- Structure for view `v_ledger`
--
DROP TABLE IF EXISTS `v_ledger`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_ledger`  AS  select `view_vouchers`.`vh_date` AS `dt`,`view_vouchers`.`vd_ledger_code` AS `act`,`view_vouchers`.`vd_dramount` AS `debit`,`view_vouchers`.`vd_cramount` AS `credit`,`view_vouchers`.`branchcode` AS `c_code` from `view_vouchers` ;

