--
-- Structure for view `v_payable`
--
DROP TABLE IF EXISTS `v_payable`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_payable`  AS  select `p2`.`bill_date` AS `dt`,`p2`.`bill_date` AS `bill_date`,`p2`.`bill_no` AS `bill_no`,`p2`.`ledger_code` AS `ledger_code`,`p2`.`net_amount` AS `total_amt`,0 AS `paid_amount`,0 AS `discount`,`p1`.`c_code` AS `c_code` from (`purc_sale` `p1` join `purc_sale_det` `p2`) where ((`p1`.`tran_code` = `p2`.`tran_code`) and (`p1`.`tran_type` = 'P') and (ifnull(`p1`.`status`,'N') <> 'C') and (`p2`.`ledger_code` <> 1) and (`p2`.`bill_date` >= cast('2019-04-01' as date))) union all select `p1`.`party_inv_date` AS `dt`,`p1`.`party_inv_date` AS `party_inv_date`,`p1`.`party_inv_no` AS `party_inv_no`,`p1`.`ledger_code` AS `ledger_code`,((ifnull(`p1`.`total_amount`,0) - ifnull((select ifnull(`p1`.`total_amt`,0) from `purc_ret` `p1` where ((`p1`.`against_invoice_code` = `p1`.`inv_code`) and (ifnull(`p1`.`status`,'N') <> 'C'))),0)) - ifnull((select ifnull(sum(`a1`.`adj_amount`),0) from (`advance_mapping_det` `a1` join `advance_mapping` `a2`) where ((`a1`.`mapping_code` = `a2`.`mapping_code`) and (ifnull(`a2`.`status`,'N') <> 'C') and (`a2`.`advance_type` = 'I') and (`a1`.`invoice_code` = `p1`.`inv_code`) and (`a2`.`c_code` = `p1`.`c_code`))),0)) AS `total_amt`,0 AS `paid_amount`,0 AS `discount`,`p1`.`c_code` AS `c_code` from `purc_inv` `p1` where ((ifnull(`p1`.`status`,'N') <> 'C') and (`p1`.`ledger_code` <> 1) and (`p1`.`party_inv_date` >= cast('2019-04-01' as date)) and (trim(`p1`.`party_inv_no`) <> '') and (`p1`.`transaction_type` = 'I')) union all select `p1`.`inv_date` AS `dt`,`p1`.`inv_date` AS `inv_date`,`p1`.`inv_no` AS `inv_no`,`p1`.`ledger_code` AS `ledger_code`,((ifnull(`p1`.`total_amount`,0) - ifnull((select ifnull(`p1`.`total_amt`,0) from `purc_ret` `p1` where ((`p1`.`against_invoice_code` = `p1`.`inv_code`) and (ifnull(`p1`.`status`,'N') <> 'C'))),0)) - ifnull((select ifnull(sum(`a1`.`adj_amount`),0) from (`advance_mapping_det` `a1` join `advance_mapping` `a2`) where ((`a1`.`mapping_code` = `a2`.`mapping_code`) and (ifnull(`a2`.`status`,'N') <> 'C') and (`a2`.`advance_type` = 'I') and (`a1`.`invoice_code` = `p1`.`inv_code`) and (`a2`.`c_code` = `p1`.`c_code`))),0)) AS `Name_exp_21`,0 AS `paid_amount`,0 AS `discount`,`p1`.`c_code` AS `c_code` from `purc_inv` `p1` where ((`p1`.`ledger_code` <> 1) and (`p1`.`inv_date` >= cast('2019-04-01' as date)) and (`p1`.`transaction_type` = 'B') and (ifnull(`p1`.`status`,'N') <> 'C')) union all select `r2`.`pay_date` AS `pay_date`,`r1`.`bill_date` AS `bill_date`,`r1`.`bill_no` AS `bill_no`,`r2`.`party_code` AS `party_code`,0 AS `0`,`r1`.`paid_amount` AS `paid_amount`,`r1`.`discount` AS `discount`,`r2`.`c_code` AS `c_code` from (`pay_det` `r1` join `pay_mast` `r2`) where ((`r1`.`pay_code` = `r2`.`pay_code`) and (ifnull(`r2`.`status`,'N') <> 'C') and (`r2`.`pay_date` >= cast('2019-04-01' as date)) and (`r1`.`tran_type` in ('P','Y','B'))) union all select `p2`.`bill_date` AS `bill_date`,`p2`.`bill_date` AS `bill_date`,`p2`.`bill_no` AS `bill_no`,`p2`.`ledger_code` AS `ledger_code`,0 AS `0`,`p2`.`net_amount` AS `net_amount`,0 AS `0`,`p1`.`c_code` AS `c_code` from (`purc_sale` `p1` join `purc_sale_det` `p2`) where ((`p1`.`tran_code` = `p2`.`tran_code`) and (`p1`.`tran_type` = 'D') and (ifnull(`p1`.`status`,'N') <> 'C') and (`p2`.`ledger_code` <> 1) and (`p2`.`bill_date` >= '2019-04-01')) union all select `p2`.`bill_date` AS `dt`,`p2`.`bill_date` AS `bill_date`,`p2`.`bill_no` AS `bill_no`,`p2`.`ledger_code` AS `ledger_code`,`p2`.`net_amount` AS `total_amt`,0 AS `paid_amount`,0 AS `discount`,`p1`.`c_code` AS `c_code` from (`purc_sale` `p1` join `purc_sale_det` `p2`) where ((`p1`.`tran_code` = `p2`.`tran_code`) and (`p1`.`tran_type` = 'Y') and (ifnull(`p1`.`status`,'N') <> 'C') and (`p2`.`ledger_code` <> 1)) union all select `advance`.`advance_date` AS `advance_date`,`advance`.`advance_date` AS `advance_date`,`advance`.`advance_no` AS `advance_no`,(case when (isnull(`l1`.`main_ledger_code`) or (`l1`.`main_ledger_code` = 0)) then `advance`.`party_ledger_code` else `l1`.`main_ledger_code` end) AS `Name_exp_52`,(`advance`.`amount` - (select ifnull(sum(`a1`.`adj_amount`),0) from (`advance_mapping_det` `a1` join `advance_mapping` `a2`) where ((`a1`.`mapping_code` = `a2`.`mapping_code`) and (`a1`.`advance_code` = `advance`.`advance_code`) and (ifnull(`a2`.`status`,'N') <> 'C')))) AS `Name_exp_53`,0 AS `0`,0 AS `0`,`advance`.`c_code` AS `c_code` from (`advance` join `ledger_mast` `l1`) where ((`advance`.`party_ledger_code` = `l1`.`ledger_code`) and (ifnull(`advance`.`status`,'N') <> 'C') and (`advance`.`advance_type` = 'I')) ;

