CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_pay_pending`  AS  select date_format(`purc_sale_det`.`bill_date`,'%d/%m/%Y') AS `bill_date`,`purc_sale_det`.`bill_date` AS `bill_dt`,`purc_sale_det`.`bill_no` AS `bill_no`,`purc_sale_det`.`ledger_code` AS `ledger_code`,`purc_sale`.`c_code` AS `c_code`,`purc_sale_det`.`amount` AS `sales_amount`,`purc_sale_det`.`cgst_amount` AS `cgst_amount`,`purc_sale_det`.`sgst_amount` AS `sgst_amount`,`purc_sale_det`.`igst_amount` AS `igst_amount`,`purc_sale_det`.`net_amount` AS `net_amount`,(select ifnull(sum((`r1`.`paid_amount` + `r1`.`discount`)),0) from (`pay_det` `r1` join `pay_mast` `r2`) where ((`r1`.`pay_code` = `r2`.`pay_code`) and (`r2`.`c_code` = `purc_sale`.`c_code`) and (`r2`.`party_code` = `purc_sale_det`.`ledger_code`) and (`r1`.`bill_no` = `purc_sale_det`.`bill_no`) and (`r1`.`bill_date` = `purc_sale_det`.`bill_date`))) AS `already_paid_amount`,(`purc_sale_det`.`net_amount` - (select ifnull(sum((`r1`.`paid_amount` + `r1`.`discount`)),0) from (`pay_det` `r1` join `pay_mast` `r2`) where ((`r1`.`pay_code` = `r2`.`pay_code`) and (`r2`.`c_code` = `purc_sale`.`c_code`) and (`r2`.`party_code` = `purc_sale_det`.`ledger_code`) and (`r1`.`bill_no` = `purc_sale_det`.`bill_no`) and (`r1`.`bill_date` = `purc_sale_det`.`bill_date`)))) AS `balance`,0 AS `discount`,0 AS `ret_amt`,'N' AS `is_paid`,0 AS `paid_amount`,`purc_sale`.`tran_type` AS `tran_type`,(case `purc_sale`.`tran_type` when 'P' then 'Purchase' when 'S' then 'Sales' when 'C' then 'Sales Return' when 'D' then 'Purchase Return' when 'O' then 'Others' end) AS `tran_type_name` from (`purc_sale` join `purc_sale_det`) where ((`purc_sale`.`tran_code` = `purc_sale_det`.`tran_code`) and (`purc_sale`.`tran_type` = 'P') and (ifnull(`purc_sale`.`status`,'N') <> 'C')) group by `purc_sale_det`.`bill_date`,`purc_sale_det`.`bill_no`,`purc_sale_det`.`amount`,`purc_sale_det`.`amount`,`purc_sale_det`.`cgst_amount`,`purc_sale_det`.`sgst_amount`,`purc_sale`.`tran_type`,`purc_sale_det`.`igst_amount`,`purc_sale_det`.`net_amount`,`purc_sale`.`c_code`,`purc_sale_det`.`ledger_code` union all select date_format(`purc_sale_det`.`bill_date`,'%d/%m/%Y') AS `bill_date`,`purc_sale_det`.`bill_date` AS `bill_dt`,`purc_sale_det`.`bill_no` AS `bill_no`,`purc_sale_det`.`ledger_code` AS `ledger_code`,`purc_sale`.`c_code` AS `c_code`,(`purc_sale_det`.`amount` * -(1)) AS `sales_amount`,`purc_sale_det`.`cgst_amount` AS `cgst_amount`,`purc_sale_det`.`sgst_amount` AS `sgst_amount`,`purc_sale_det`.`igst_amount` AS `igst_amount`,0 AS `0`,(select ifnull(sum((`r1`.`paid_amount` + `r1`.`discount`)),0) from (`pay_det` `r1` join `pay_mast` `r2`) where ((`r1`.`pay_code` = `r2`.`pay_code`) and (`r2`.`c_code` = `purc_sale`.`c_code`) and (`r2`.`party_code` = `purc_sale_det`.`ledger_code`) and (`r1`.`bill_no` = `purc_sale_det`.`bill_no`) and (`r1`.`bill_date` = `purc_sale_det`.`bill_date`))) AS `already_paid_amount`,((`purc_sale_det`.`net_amount` * -(1)) - (select ifnull(sum((`r1`.`paid_amount` + `r1`.`discount`)),0) from (`pay_det` `r1` join `pay_mast` `r2`) where ((`r1`.`pay_code` = `r2`.`pay_code`) and (`r2`.`c_code` = `purc_sale`.`c_code`) and (`r2`.`party_code` = `purc_sale_det`.`ledger_code`) and (`r1`.`bill_no` = `purc_sale_det`.`bill_no`) and (`r1`.`bill_date` = `purc_sale_det`.`bill_date`)))) AS `balance`,0 AS `discount`,0 AS `0`,'N' AS `is_paid`,0 AS `paid_amount`,`purc_sale`.`tran_type` AS `tran_type`,(case `purc_sale`.`tran_type` when 'P' then 'Purchase' when 'S' then 'Sales' when 'C' then 'Sales Return' when 'D' then 'Purchase Return' when 'O' then 'Others' end) AS `tran_type_name` from (`purc_sale` join `purc_sale_det`) where ((`purc_sale`.`tran_code` = `purc_sale_det`.`tran_code`) and (`purc_sale`.`tran_type` = 'D') and (ifnull(`purc_sale`.`status`,'N') <> 'C')) group by `purc_sale_det`.`bill_date`,`purc_sale_det`.`bill_no`,`purc_sale_det`.`amount`,`purc_sale_det`.`amount`,`purc_sale_det`.`cgst_amount`,`purc_sale_det`.`sgst_amount`,`purc_sale`.`tran_type`,`purc_sale_det`.`igst_amount`,`purc_sale_det`.`net_amount`,`purc_sale`.`c_code`,`purc_sale_det`.`ledger_code` union all select date_format(`purc_sale_det`.`bill_date`,'%d/%m/%Y') AS `bill_date`,`purc_sale_det`.`bill_date` AS `bill_dt`,`purc_sale_det`.`bill_no` AS `bill_no`,`purc_sale_det`.`ledger_code` AS `ledger_code`,`purc_sale`.`c_code` AS `c_code`,`purc_sale_det`.`amount` AS `sales_amount`,`purc_sale_det`.`cgst_amount` AS `cgst_amount`,`purc_sale_det`.`sgst_amount` AS `sgst_amount`,`purc_sale_det`.`igst_amount` AS `igst_amount`,0 AS `0`,(select ifnull(sum((`r1`.`paid_amount` + `r1`.`discount`)),0) from (`pay_det` `r1` join `pay_mast` `r2`) where ((`r1`.`pay_code` = `r2`.`pay_code`) and (`r2`.`c_code` = `purc_sale`.`c_code`) and (`r2`.`party_code` = `purc_sale_det`.`ledger_code`) and (`r1`.`bill_no` = `purc_sale_det`.`bill_no`) and (`r1`.`bill_date` = `purc_sale_det`.`bill_date`))) AS `already_paid_amount`,(`purc_sale_det`.`net_amount` - (select ifnull(sum((`r1`.`paid_amount` + `r1`.`discount`)),0) from (`pay_det` `r1` join `pay_mast` `r2`) where ((`r1`.`pay_code` = `r2`.`pay_code`) and (`r2`.`c_code` = `purc_sale`.`c_code`) and (`r2`.`party_code` = `purc_sale_det`.`ledger_code`) and (`r1`.`bill_no` = `purc_sale_det`.`bill_no`) and (`r1`.`bill_date` = `purc_sale_det`.`bill_date`)))) AS `balance`,0 AS `discount`,0 AS `0`,'N' AS `is_paid`,0 AS `paid_amount`,`purc_sale`.`tran_type` AS `tran_type`,(case `purc_sale`.`tran_type` when 'P' then 'Purchase' when 'S' then 'Sales' when 'C' then 'Sales Return' when 'D' then 'Purchase Return' when 'O' then 'Others' end) AS `tran_type_name` from (`purc_sale` join `purc_sale_det`) where ((`purc_sale`.`tran_code` = `purc_sale_det`.`tran_code`) and (`purc_sale`.`tran_type` = 'O') and (ifnull(`purc_sale`.`status`,'N') <> 'C')) group by `purc_sale_det`.`bill_date`,`purc_sale_det`.`bill_no`,`purc_sale_det`.`amount`,`purc_sale_det`.`amount`,`purc_sale_det`.`cgst_amount`,`purc_sale_det`.`sgst_amount`,`purc_sale`.`tran_type`,`purc_sale_det`.`igst_amount`,`purc_sale_det`.`net_amount`,`purc_sale`.`c_code`,`purc_sale_det`.`ledger_code` union all select date_format(`advance`.`advance_date`,'%d/%m/%Y') AS `bill_date`,`advance`.`advance_date` AS `bill_dt`,`advance`.`advance_no` AS `advance_no`,`advance`.`party_ledger_code` AS `party_ledger_code`,`advance`.`c_code` AS `c_code`,`advance`.`amount` AS `sales_amount`,0 AS `0`,0 AS `0`,0 AS `0`,`advance`.`amount` AS `amount`,ifnull(sum(`r1`.`paid_amount`),0) AS `already_paid_amount`,(`advance`.`amount` - ifnull(sum((`r1`.`paid_amount` + `r1`.`discount`)),0)) AS `balance`,0 AS `discount`,0 AS `0`,'N' AS `is_paid`,0 AS `paid_amount`,'A' AS `tran_type`,'Advance' AS `Advance` from (`advance` left join `pay_det` `r1` on(((`r1`.`bill_date` = `advance`.`advance_date`) and (`r1`.`bill_no` = `advance`.`advance_no`)))) where (ifnull(`advance`.`status`,'N') <> 'C') group by `advance`.`advance_date`,`advance`.`advance_no`,`advance`.`advance_code`,`advance`.`amount`,`advance`.`c_code`,`advance`.`party_ledger_code` order by `bill_dt` ;

