DROP TABLE IF EXISTS `v_product_movement`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_product_movement`  AS  select `p1`.`prod_code` AS `prod_code`,`i1`.`product_code` AS `product_code`,`p1`.`product_name` AS `product_name`,max(`i2`.`inward_date`) AS `last_inward_date`,NULL AS `last_invoice_date`,0 AS `stock_pcs`,0 AS `stock_mtrs` from ((`product_mast` `p1` join `inward_det` `i1`) join `inward` `i2`) where ((`p1`.`product_code` = `i1`.`product_code`) and (`i1`.`inward_code` = `i2`.`inward_code`)) group by `p1`.`prod_code`,`i1`.`product_code`,`p1`.`product_name` union all select `p1`.`prod_code` AS `prod_code`,`f2`.`design_code` AS `design_code`,`p1`.`product_name` AS `product_name`,NULL AS `NULL`,max(`f1`.`bill_date`) AS `max(bill_date)`,0 AS `0`,0 AS `0` from ((`f_invoice` `f1` join `f_invoice_det` `f2`) join `product_mast` `p1`) where ((`f1`.`invoice_code` = `f2`.`invoice_code`) and (`f2`.`design_code` = `p1`.`product_code`) and (`f1`.`c_code` <> 3)) group by `p1`.`prod_code`,`f2`.`design_code`,`p1`.`product_name` union all select `p1`.`prod_code` AS `prod_code`,`p1`.`product_code` AS `product_code`,`p1`.`product_name` AS `product_name`,NULL AS `NULL`,NULL AS `NULL`,sum(`v1`.`qty`) AS `sum(qty)`,sum(`v1`.`mtrs`) AS `sum(mtrs)` from (`v_stock` `v1` join `product_mast` `p1`) where (`v1`.`product_code` = `p1`.`product_code`) group by `p1`.`prod_code`,`p1`.`product_code`,`p1`.`product_name` ;

