DROP TABLE IF EXISTS `v_purchase`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_purchase`  AS  select `l1`.`local_interstate` AS `local_interstate`,`f2`.`bill_date` AS `bill_dt`,`f2`.`bill_no` AS `bill_no`,`l1`.`ledger_name` AS `ledger_name`,`l1`.`branch` AS `branch`,`l1`.`gstin_no` AS `gstin_no`,(select `p1`.`place_of_supply` from `place_of_supply_mast` `p1` where (`p1`.`place_of_supply_code` = `l1`.`place_of_supply_code`)) AS `place_of_supply`,`f2`.`gst_per` AS `tax_perc`,`f2`.`amount` AS `sale_amount`,`f2`.`freight` AS `freight`,(`f2`.`gst_per` / 2) AS `cgst_per`,`f2`.`cgst_amount` AS `cgst_amount`,(`f2`.`gst_per` / 2) AS `sgst_per`,`f2`.`sgst_amount` AS `sgst_amount`,`f2`.`gst_per` AS `igst_per`,`f2`.`igst_amount` AS `igst_amount`,`f2`.`net_amount` AS `total_amt`,`f1`.`c_code` AS `c_code` from (((`purc_sale` `f1` join `purc_sale_det` `f2`) join `ledger_mast` `l1`) join `company`) where ((`f1`.`tran_code` = `f2`.`tran_code`) and (`f2`.`ledger_code` = `l1`.`ledger_code`) and (`f1`.`c_code` = `company`.`c_code`) and (`f1`.`tran_type` = 'P')) ;

