CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_purc_hsn_summary`  AS  select `p1`.`bill_date` AS `bill_date`,`p1`.`bill_no` AS `bill_no`,`p1`.`hsn_code` AS `hsn_code`,`p1`.`qty` AS `total_qty`,`p1`.`net_amount` AS `total_value`,`p1`.`amount` AS `taxable_value`,`p1`.`igst_amount` AS `igst_amount`,`p1`.`cgst_amount` AS `cgst_amount`,`p1`.`sgst_amount` AS `sgst_amount`,0 AS `cess`,0 AS `round_off`,`p2`.`c_code` AS `c_code` from (`purc_sale_det` `p1` join `purc_sale` `p2`) where ((`p1`.`tran_code` = `p2`.`tran_code`) and (ifnull(`p2`.`status`,'N') <> 'C') and (`p2`.`tran_type` = 'P')) union all select `p2`.`inv_date` AS `inv_date`,`p2`.`inv_no` AS `inv_no`,`p1`.`hsn_code` AS `hsn_code`,sum(`p1`.`qty`) AS `total_qty`,(((round(sum(`p1`.`taxable_amt`),2) + round(((sum(`p1`.`taxable_amt`) * `p2`.`igst_per`) / 100),2)) + round(((sum(`p1`.`taxable_amt`) * `p2`.`cgst_per`) / 100),2)) + round(((sum(`p1`.`taxable_amt`) * `p2`.`sgst_per`) / 100),2)) AS `total_value`,round(sum(`p1`.`taxable_amt`),2) AS `taxable_value`,round(((sum(`p1`.`taxable_amt`) * `p2`.`igst_per`) / 100),2) AS `round(sum(taxable_amt)*igst_per/100,2)`,round(((sum(`p1`.`taxable_amt`) * `p2`.`cgst_per`) / 100),2) AS `round(sum(taxable_amt)*cgst_per/100,2)`,round(((sum(`p1`.`taxable_amt`) * `p2`.`sgst_per`) / 100),2) AS `round(sum(taxable_amt)*sgst_per/100,2)`,0 AS `0`,0 AS `0`,`p2`.`c_code` AS `c_code` from (`purc_inv_det` `p1` join `purc_inv` `p2`) where ((`p1`.`inv_code` = `p2`.`inv_code`) and (ifnull(`p2`.`status`,'N') <> 'C') and (`p2`.`transaction_type` = 'B')) group by `p2`.`inv_date`,`p1`.`hsn_code`,`p2`.`party_inv_no` union all select `p2`.`party_inv_date` AS `party_inv_date`,`p2`.`party_inv_no` AS `party_inv_no`,`p1`.`hsn_code` AS `hsn_code`,sum(`p1`.`qty`) AS `total_qty`,(((round(sum(`p1`.`taxable_amt`),2) + round(((sum(`p1`.`taxable_amt`) * `p2`.`igst_per`) / 100),2)) + round(((sum(`p1`.`taxable_amt`) * `p2`.`cgst_per`) / 100),2)) + round(((sum(`p1`.`taxable_amt`) * `p2`.`sgst_per`) / 100),2)) AS `total_value`,round(sum(`p1`.`taxable_amt`),2) AS `taxable_value`,round(((sum(`p1`.`taxable_amt`) * `p2`.`igst_per`) / 100),2) AS `round(sum(taxable_amt)*igst_per/100,2)`,round(((sum(`p1`.`taxable_amt`) * `p2`.`cgst_per`) / 100),2) AS `round(sum(taxable_amt)*cgst_per/100,2)`,round(((sum(`p1`.`taxable_amt`) * `p2`.`sgst_per`) / 100),2) AS `round(sum(taxable_amt)*sgst_per/100,2)`,0 AS `0`,0 AS `0`,`p2`.`c_code` AS `c_code` from (`purc_inv_det` `p1` join `purc_inv` `p2`) where ((`p1`.`inv_code` = `p2`.`inv_code`) and (ifnull(`p2`.`status`,'N') <> 'C') and (`p2`.`transaction_type` = 'I') and (trim(`p2`.`party_inv_no`) <> '')) group by `p2`.`inv_date`,`p1`.`hsn_code`,`p2`.`party_inv_no` union all select `p2`.`bill_date` AS `bill_date`,`p2`.`bill_no` AS `bill_no`,`p1`.`hsn_code` AS `hsn_code`,(`p1`.`pcs` * -(1)) AS `total_qty`,(`p2`.`total_amt` * -(1)) AS `total_value`,(`p1`.`amount` * -(1)) AS `taxable_value`,(`p2`.`igst_amount` * -(1)) AS `igst_amount*-1`,(`p2`.`cgst_amount` * -(1)) AS `cgst_amount*-1`,(`p2`.`sgst_amount` * -(1)) AS `sgst_amount*-1`,0 AS `0`,0 AS `0`,`p2`.`c_code` AS `c_code` from (`purc_ret_det` `p1` join `purc_ret` `p2`) where ((`p1`.`invoice_code` = `p2`.`invoice_code`) and (ifnull(`p2`.`status`,'N') <> 'C')) union all select `f1`.`inv_date` AS `inv_date`,`f1`.`inv_no` AS `inv_no`,`f2`.`hsn_code` AS `hsn_code`,0 AS `0`,0 AS `0`,0 AS `0`,0 AS `0`,0 AS `0`,0 AS `0`,0 AS `0`,`f1`.`round_off` AS `round_off`,`f1`.`c_code` AS `c_code` from (`purc_inv` `f1` join `purc_inv_det` `f2`) where ((`f1`.`inv_code` = `f2`.`inv_code`) and (`f2`.`sno` = 1) and (ifnull(`f1`.`status`,'N') <> 'C') and (`f1`.`transaction_type` = 'B')) union all select `f1`.`party_inv_date` AS `party_inv_date`,`f1`.`party_inv_no` AS `party_inv_no`,`f2`.`hsn_code` AS `hsn_code`,0 AS `0`,0 AS `0`,0 AS `0`,0 AS `0`,0 AS `0`,0 AS `0`,0 AS `0`,`f1`.`round_off` AS `round_off`,`f1`.`c_code` AS `c_code` from (`purc_inv` `f1` join `purc_inv_det` `f2`) where ((`f1`.`inv_code` = `f2`.`inv_code`) and (`f2`.`sno` = 1) and (ifnull(`f1`.`status`,'N') <> 'C') and (`f1`.`transaction_type` = 'I') and (trim(`f1`.`party_inv_no`) <> '')) union all select `f1`.`bill_date` AS `bill_date`,`f1`.`bill_no` AS `bill_no`,`f2`.`hsn_code` AS `hsn_code`,0 AS `0`,0 AS `0`,0 AS `0`,0 AS `0`,0 AS `0`,0 AS `0`,0 AS `0`,(`f1`.`round_off` * 1) AS `round_off*1`,`f1`.`c_code` AS `c_code` from (`purc_ret` `f1` join `purc_ret_det` `f2`) where ((`f1`.`invoice_code` = `f2`.`invoice_code`) and (`f2`.`sno` = 1) and (ifnull(`f1`.`status`,'N') <> 'C')) ;

