CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_purc_rate`  AS  select distinct `i2`.`inward_date` AS `inward_date`,`i1`.`product_code` AS `product_code`,ifnull(`i1`.`rate`,0) AS `rate` from (`inward_det` `i1` join `inward` `i2`) where ((`i1`.`inward_code` = `i2`.`inward_code`) and (ifnull(`i2`.`status`,'N') <> 'C')) order by `i1`.`product_code`,`i2`.`inward_date` desc ;

