CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_purc_tax`  AS  select `p2`.`bill_no` AS `bill_no`,`p2`.`bill_date` AS `bill_date`,`l1`.`ledger_name` AS `ledger_name`,`l1`.`ledger_code` AS `ledger_code`,`l1`.`branch` AS `branch`,`p2`.`qty` AS `qty`,`p2`.`unit_name` AS `unit_name`,`p2`.`amount` AS `amount`,`p2`.`freight` AS `freight`,`p2`.`discount` AS `discount`,`p2`.`cgst_amount` AS `cgst_amount`,`p2`.`sgst_amount` AS `sgst_amount`,`p2`.`igst_amount` AS `igst_amount`,`p2`.`net_amount` AS `total_amt`,`p1`.`c_code` AS `c_code` from ((`ledger_mast` `l1` join `purc_sale` `p1`) join `purc_sale_det` `p2`) where ((`p1`.`tran_code` = `p2`.`tran_code`) and (`p2`.`ledger_code` = `l1`.`ledger_code`) and (`p1`.`tran_type` = 'P') and (ifnull(`p1`.`status`,'N') <> 'C')) union all select `p2`.`bill_no` AS `bill_no`,`p2`.`bill_date` AS `bill_date`,`l1`.`ledger_name` AS `ledger_name`,`l1`.`ledger_code` AS `ledger_code`,`l1`.`branch` AS `branch`,`p2`.`qty` AS `qty`,`p2`.`unit_name` AS `unit_name`,(`p2`.`amount` * -(1)) AS `amount`,(`p2`.`freight` * -(1)) AS `freight*-1`,(`p2`.`discount` * -(1)) AS `discount*-1`,(`p2`.`cgst_amount` * -(1)) AS `cgst_amount*-1`,(`p2`.`sgst_amount` * -(1)) AS `sgst_amount*-1`,(`p2`.`igst_amount` * -(1)) AS `igst_amount*-1`,(`p2`.`net_amount` * -(1)) AS `net_amount*-1`,`p1`.`c_code` AS `c_code` from ((`ledger_mast` `l1` join `purc_sale` `p1`) join `purc_sale_det` `p2`) where ((`p1`.`tran_code` = `p2`.`tran_code`) and (`p2`.`ledger_code` = `l1`.`ledger_code`) and (`p1`.`tran_type` = 'D') and (ifnull(`p1`.`status`,'N') <> 'C')) union all select `p1`.`bill_no` AS `bill_no`,`p1`.`bill_date` AS `bill_date`,`l1`.`ledger_name` AS `ledger_name`,`l1`.`ledger_code` AS `ledger_code`,`l1`.`branch` AS `branch`,ifnull(sum(`p2`.`pcs`),0) AS `ifnull(sum(pcs),0)`,`p3`.`unit_name` AS `unit_name`,(`p1`.`tot` * -(1)) AS `amount`,0 AS `0`,(`p1`.`discount` * -(1)) AS `discount*-1`,(`p1`.`cgst_amount` * -(1)) AS `cgst_amount*-1`,(`p1`.`sgst_amount` * -(1)) AS `sgst_amount*-1`,(`p1`.`igst_amount` * -(1)) AS `igst_amount*-1`,(`p1`.`total_amt` * -(1)) AS `total_amt*-1`,`p1`.`c_code` AS `c_code` from (((`ledger_mast` `l1` join `purc_ret` `p1`) join `purc_ret_det` `p2`) join `unit_mast` `p3`) where ((`p1`.`invoice_code` = `p2`.`invoice_code`) and (`p2`.`unit_code` = `p3`.`unit_code`) and (`p1`.`ledger_code` = `l1`.`ledger_code`) and (ifnull(`p1`.`status`,'N') <> 'C')) group by `p1`.`bill_no`,`p1`.`bill_date`,`l1`.`ledger_name`,`l1`.`ledger_code`,`l1`.`branch`,`p1`.`discount`,`p1`.`cgst_amount`,`p1`.`sgst_amount`,`p1`.`igst_amount`,`p1`.`total_amt`,`p1`.`c_code` union all select `p1`.`party_inv_no` AS `bill_no`,`p1`.`party_inv_date` AS `party_inv_date`,`l1`.`ledger_name` AS `ledger_name`,`l1`.`ledger_code` AS `ledger_code`,`l1`.`branch` AS `branch`,sum(`p2`.`qty`) AS `sum(qty)`,`u1`.`unit_name` AS `unit_name`,sum(`p2`.`amount`) AS `sum(amount)`,0 AS `0`,`p1`.`discount` AS `discount`,`p1`.`cgst_amount` AS `cgst_amount`,`p1`.`sgst_amount` AS `sgst_amount`,`p1`.`igst_amount` AS `igst_amount`,`p1`.`total_amount` AS `total_amt`,`p1`.`c_code` AS `c_code` from (((`ledger_mast` `l1` join `purc_inv` `p1`) join `purc_inv_det` `p2`) join `unit_mast` `u1`) where ((`p2`.`unit_code` = `u1`.`unit_code`) and (`p1`.`inv_code` = `p2`.`inv_code`) and (`p1`.`ledger_code` = `l1`.`ledger_code`) and (ifnull(`p1`.`status`,'N') <> 'C') and (trim(`p1`.`party_inv_no`) <> '') and (`p1`.`transaction_type` = 'I')) group by `p1`.`party_inv_no`,`p1`.`party_inv_date`,`l1`.`ledger_name`,`l1`.`branch`,`l1`.`ledger_code`,`p1`.`discount`,`p1`.`cgst_amount`,`p1`.`sgst_amount`,`p1`.`igst_amount`,`total_amt`,`p1`.`c_code` union all select `p1`.`inv_no` AS `bill_no`,`p1`.`inv_date` AS `inv_date`,`l1`.`ledger_name` AS `ledger_name`,`l1`.`ledger_code` AS `ledger_code`,`l1`.`branch` AS `branch`,sum(`p2`.`qty`) AS `sum(qty)`,`u1`.`unit_name` AS `unit_name`,sum(`p2`.`amount`) AS `sum(amount)`,0 AS `0`,`p1`.`discount` AS `discount`,`p1`.`cgst_amount` AS `c