) and (`p2`.`ledger_code` <> 1) and (`p2`.`bill_date` >= cast('2019-04-01' as date))) union all select `r2`.`rece_date` AS `rece_date`,`r1`.`bill_date` AS `bill_date`,`r1`.`bill_no` AS `bill_no`,(case when (isnull(`l1`.`main_ledger_code`) or (`l1`.`main_ledger_code` = 0)) then `r2`.`party_code` else `l1`.`main_ledger_code` end) AS `Name_exp_28`,0 AS `0`,`r1`.`paid_amount` AS `paid_amount`,`r1`.`discount` AS `discount`,`r2`.`c_code` AS `c_code` from ((`rece_det` `r1` join `rece_mast` `r2`) join `ledger_mast` `l1`) where ((`r2`.`party_code` = `l1`.`ledger_code`) and (`r1`.`rece_code` = `r2`.`rece_code`) and (ifnull(`r2`.`status`,'N') <> 'C')) union all select `advance`.`advance_date` AS `advance_date`,`advance`.`advance_date` AS `advance_date`,`advance`.`advance_no` AS `advance_no`,(case when (isnull(`l1`.`main_ledger_code`) or (`l1`.`main_ledger_code` = 0)) then `advance`.`party_ledger_code` else `l1`.`main_ledger_code` end) AS `Name_exp_36`,(`advance`.`amount` - (select ifnull(sum(`a1`.`adj_amount`),0) from (`advance_mapping_det` `a1` join `advance_mapping` `a2`) where ((`a1`.`mapping_code` = `a2`.`mapping_code`) and (`a1`.`advance_code` = `advance`.`advance_code`) and (ifnull(`a2`.`status`,'N') <> 'C')))) AS `Name_exp_37`,0 AS `0`,0 AS `0`,`advance`.`c_code` AS `c_code` from (`advance` join `ledger_mast` `l1`) where ((`advance`.`party_ledger_code` = `l1`.`ledger_code`) and (ifnull(`advance`.`status`,'N') <> 'C') and (`advance`.`advance_type` = 'R')) union all select `p2`.`bill_date` AS `bill_date`,`p2`.`bill_date` AS `bill_date`,`p2`.`bill_no` AS `bill_no`,(case when (isnull(`l1`.`main_ledger_code`) or (`l1`.`main_ledger_code` = 0)) then `l1`.`ledger_code` else `l1`.`main_ledger_code` end) AS `Name_exp_44`,(`p2`.`net_amount` * -(1)) AS `net_amount*-1`,0 AS `0`,0 AS `0`,`p1`.`c_code` AS `c_code` from ((`purc_sale` `p1` join `purc_sale_det` `p2`) join `ledger_mast` `l1`) where ((`p2`.`ledger_code` = `l1`.`ledger_code`) and (`p1`.`tran_code` = `p2`.`tran_code`) and (`p1`.`tran_type` = 'C') and (ifnull(`p1`.`status`,'N') <> 'C') and (`p2`.`ledger_code` <> 1) and (`p2`.`bill_date` >= cast('2019-04-01' as date))) union all select `p2`.`bill_date` AS `bill_date`,`p2`.`bill_date` AS `bill_date`,`p2`.`bill_no` AS `bill_no`,(case when (isnull(`l1`.`main_ledger_code`) or (`l1`.`main_ledger_code` = 0)) then `l1`.`ledger_code` else `l1`.`main_ledger_code` end) AS `Name_exp_52`,`p2`.`net_amount` AS `net_amount`,0 AS `0`,0 AS `0`,`p1`.`c_code` AS `c_code` from ((`purc_sale` `p1` join `purc_sale_det` `p2`) join `ledger_mast` `l1`) where ((`p2`.`ledger_code` = `l1`.`ledger_code`) and (`p1`.`tran_code` = `p2`.`tran_code`) and (`p1`.`tran_type` = 'Z') and (ifnull(`p1`.`status`,'N') <> 'C') and (`p2`.`ledger_code` <> 1)) ;

