urc_sale_det`.`igst_amount`,`purc_sale_det`.`net_amount`,`purc_sale`.`c_code`,`purc_sale_det`.`ledger_code` union all select date_format(`purc_sale_det`.`bill_date`,'%d/%m/%Y') AS `bill_date`,`purc_sale_det`.`bill_date` AS `bill_dt`,`purc_sale_det`.`bill_no` AS `bill_no`,`purc_sale_det`.`ledger_code` AS `ledger_code`,`purc_sale`.`c_code` AS `c_code`,(`purc_sale_det`.`amount` * -(1)) AS `sales_amount`,`purc_sale_det`.`cgst_amount` AS `cgst_amount`,`purc_sale_det`.`sgst_amount` AS `sgst_amount`,`purc_sale_det`.`igst_amount` AS `igst_amount`,0 AS `0`,(select ifnull(sum((`r1`.`paid_amount` + `r1`.`discount`)),0) from (`rece_det` `r1` join `rece_mast` `r2`) where ((`r1`.`rece_code` = `r2`.`rece_code`) and (`r2`.`c_code` = `purc_sale`.`c_code`) and (`r2`.`party_code` = `purc_sale_det`.`ledger_code`) and (`r1`.`bill_no` = `purc_sale_det`.`bill_no`) and (`r1`.`bill_date` = `purc_sale_det`.`bill_date`))) AS `already_paid_amount`,((`purc_sale_det`.`net_amount` * -(1)) - (select ifnull(sum((`r1`.`paid_amount` + `r1`.`discount`)),0) from (`rece_det` `r1` join `rece_mast` `r2`) where ((`r1`.`rece_code` = `r2`.`rece_code`) and (`r2`.`c_code` = `purc_sale`.`c_code`) and (`r2`.`party_code` = `purc_sale_det`.`ledger_code`) and (`r1`.`bill_no` = `purc_sale_det`.`bill_no`) and (`r1`.`bill_date` = `purc_sale_det`.`bill_date`)))) AS `balance`,0 AS `discount`,0 AS `0`,'N' AS `is_paid`,0 AS `paid_amount`,`purc_sale`.`tran_type` AS `tran_type`,(case `purc_sale`.`tran_type` when 'P' then 'Purchase' when 'S' then 'Sales' when 'C' then 'Sales Return' when 'D' then 'Purchase Return' end) AS `tran_type_name` from (`purc_sale` join `purc_sale_det`) where ((`purc_sale`.`tran_code` = `purc_sale_det`.`tran_code`) and (`purc_sale`.`tran_type` = 'C') and (ifnull(`purc_sale`.`status`,'N') <> 'C')) group by `purc_sale_det`.`bill_date`,`purc_sale_det`.`bill_no`,`purc_sale_det`.`amount`,`purc_sale_det`.`amount`,`purc_sale_det`.`cgst_amount`,`purc_sale_det`.`sgst_amount`,`purc_sale`.`tran_type`,`purc_sale