` AS `c_code`,`advance`.`amount` AS `sales_amount`,0 AS `0`,0 AS `0`,0 AS `0`,(`advance`.`amount` * -(1)) AS `advance.amount*-1`,ifnull(sum(`r1`.`paid_amount`),0) AS `already_paid_amount`,((`advance`.`amount` - ifnull(sum((`r1`.`paid_amount` + `r1`.`discount`)),0)) * -(1)) AS `balance`,0 AS `discount`,0 AS `0`,'N' AS `is_paid`,0 AS `paid_amount`,'A' AS `tran_type`,'Advance' AS `Advance` from (`advance` left join `rece_det` `r1` on(((`r1`.`bill_date` = `advance`.`advance_date`) and (`r1`.`bill_no` = `advance`.`advance_no`)))) where (ifnull(`advance`.`status`,'N') <> 'C') group by `advance`.`advance_date`,`advance`.`advance_no`,`advance`.`advance_code`,`advance`.`amount`,`advance`.`c_code`,`advance`.`party_ledger_code` order by `bill_dt` ;

