('yarn_purc_list', 'select bill_no,bill_date,ledger_name,net_amount,purc_code from yarn_purc y1, ledger_mast l1 where y1.ledger_code=l1.ledger_code and ifnull(y1.status,\'N\')<>\'C\' ', 'bill_no,bill_date,ledger_name,net_amount,purc_code', 'bill_no,bill_date,ledger_name,net_amount,purc_code', 'bill_no', '100,100,200,100,100', 'BillNo,Date,Supplier,NetAmt,Code', 'text,date,int,deci,int', 1000, 'left,left,left,left,left', 'bill_date asc', 'Yarn Purchase');
