(800024, 'purc_value', 'Purchase Value', 1, 120, 'text', 'right', NULL, NULL, NULL, 4, NULL, NULL, 'decimal', '', '(select ifnull(sum(amount),0) \r\nfrom purc_sale_det f1,purc_sale f2 where f1.tran_code=f2.tran_code and tran_type=\'P\' and ifnull(status,\'N\')<>\'C\' and  (month(f1.bill_date)=m1.mth_no and year(f1.bill_date)=m1.year and f2.c_code=$(companycode) and $(fromdate) $(todate))) - (select ifnull(sum(amount),0) \r\nfrom purc_sale_det f1,purc_sale f2 where f1.tran_code=f2.tran_code and tran_type=\'D\' and ifnull(status,\'N\')<>\'C\' and  (month(f1.bill_date)=m1.mth_no and year(f1.bill_date)=m1.year and f2.c_code=$(companycode) and $(fromdate) $(todate)))', 0, 0, 'purc_value', 70, 4, 0, 1, 0, ''),
