(600041, 'fabric_order', 'Fabric Order', 'select order_no from fabric_order', 0, NULL, '', 'select order_node,order_no,order_date from fabric_order', 0, 0, 0, 'b/f', NULL, '', 'order_no', 'asc', 0, 0, 0, 0, '', '', '', '', '', '', 0, 0, '', ''),
(800001, 'sales_register', 'Sales Register', 'select comp_name, concat(\'Sales Register From \', DATE_FORMAT(\'$(fromdate)\',\'%d/%m/%Y\'), \' To \',DATE_FORMAT(\'$(todate)\',\'%d/%m/%Y\')) from company where company.c_code=$(companycode)', 0, NULL, 'companycode,trantype', '\r\nselect invoice_code,row_type,bill_no as bill_no,bill_dt,bill_dt1,ledger_name,branch,sum(amount) as  amount,discount,sum(taxable_amount) as taxable_amount,freight,cgst_amount,sgst_amount,igst_amount,total_amt   from(select f_invoice.invoice_code,1 row_type,bill_no as bill_no,DATE_FORMAT(bill_date,\'%d/%m/%Y\') bill_dt,bill_date bill_dt1,ledger_name,branch,amount as  amount,discount,taxable_amt as taxable_amount,courier_charges as freight,cgst_amount,sgst_amount,igst_amount,total_amt  \r\nfrom f_invoice,f_invoice_det,ledger_mast  where f_invoice.invoice_code=f_invoice_det.invoice_code and  f_invoice.ledger_code=ledger_mast.ledger_code and ifnull(status,\'N\')<>\'C\' and (\'$(trantype)\'=\'S\' or \'$(trantype)\'=\'A\') and c_code=$(companycode) and $(fromdate) $(todate)\r\n\r\n\r\nunion all \r\n\r\nselect sales_ret.invoice_code,2 row_type,bill_no as bill_no,DATE_FORMAT(bill_date,\'%d/%m/%Y\') bill_dt,bill_date bill_dt1,ledger_name,branch,amount*-1 as  amount,discount*-1,taxable_amt*-1 as taxable_amount,courier_charges as freight,cgst_amount*-1,sgst_amount*-1,igst_amount*-1,total_amt*-1  \r\nfrom sales_ret,sales_ret_det,ledger_mast  where sales_ret.invoice_code=sales_ret_det.invoice_code and  sales_ret.ledger_code=ledger_mast.ledger_code and ifnull(status,\'N\')<>\'C\' and (\'$(trantype)\'=\'C\' or \'$(trantype)\'=\'A\') and c_code=$(companycode) and $(fromdate) $(todate)\r\n\r\nunion all \r\n\r\nselect 0 invoice_code,3 row_type,bill_no,DATE_FORMAT(bill_date,\'%d/%m/%Y\'),bill_date bill_dt1,ledger_name,branch,amount*-1,discount*-1,(amount-discount)*-1,freight*-1,cgst_amount*-1,sgst_amount*-1,igst_amount*-1,net_amount*-1  \r\nfrom purc_sale_det p1,purc_sale p2,ledger_mast l1 where p1.tran_code=p2.tran_code and p1.ledger_code=l1.ledger_code  and ifnull(status,\'N\')<>\'C\' and (\'$(trantype)\'=\'S\' or \'$(trantype)\'=\'C\') and c_code=$(companycode) and $(fromdate) $(todate) and tran_type=\'C\') a where 1=1   group by bill_dt,bill_dt1,bill_no,ledger_name,branch,discount,freight,cgst_amount,sgst_amount,igst_amount,total_amt', 0, 0, 0, 'b/f', NULL, 'TEXT,TEXT', 'bill_dt1,bill_no', 'asc', 1, 1, 0, 0, '', '', '', '', '', '', 0, 0, '', ''),
(800002, 'sals_register_party', 'Sales - Party wise', 'select comp_name, concat(\'Sales Register From \', DATE_FORMAT(\'$(fromdate)\',\'%d/%m/%Y\'), \' To \',DATE_FORMAT(\'$(todate)\',\'%d/%m/%Y\')),concat(\'Party: \',\'$(ledger)\')   from company where company.c_code=$(companycode)', 0, NULL, 'companycode', 'SELECT DATE_FORMAT(f_invoice.bill_date,\'%d/%m/%Y\') as bill_date, ledger_mast.ledger_name as ledger_name, ledger_mast.place as place, f_invoice.bill_no bill_no, mtrs as mtrs,  pcs as pcs,sales_amount as sales_amount,discount,sales_amount-discount as taxable_amount,cgst_amount,sgst_amount,igst_amount,f_invoice.transport_charges as freight,case when paid_to_pay=\'P\' then freight else 0 end as freight_amt,lr_no, f_invoice.total_amt as net_amount  FROM f_invoice,v_sales_det_sum,ledger_mast , company WHERE f_invoice.invoice_code=v_sales_det_sum.invoice_code and  (ledger_mast.ledger_code = f_invoice.ledger_code) and ifnull(status,\'N\')<>\'C\'  and f_invoice.c_code=company.c_code and f_invoice.c_code=$(companycode)  and  $(fromdate) $(todate) $(ledger)', 0, 0, 0, 'b/f', NULL, '', 'date(bill_date),bill_no', 'asc', 1, 1, 0, 0, '', '', '', '', '', '', 0, 0, '', ''),
(800003, 'sales_register_design_all', 'Design Wise - Sales Register', 'select comp_name, concat(\'Sales Register From \', DATE_FORMAT(\'$(fromdate)\',\'%d/%m/%Y\'), \' To \',DATE_FORMAT(\'$(todate)\',\'%d/%m/%Y\')) from company where company.c_code=$(companycode)', 0, NULL, 'companycode', 'SELECT DATE_FORMAT(f_invoice.bill_date,\'%d/%m/%Y\')  as bill_date, ledger_mast.ledger_name as ledger_name, ledger_mast.branch as place, f_invoice.bill_no bill_no, product_name,f_invoice_det.mtrs as mtrs,  f_invoice_det.pcs as pcs,f_invoice_det.rate as rate,f_invoice_det.amount as amount,f_invoice.disc_per as disc_per,round((f_invoice_det.amount*\r\ndisc_per /100),2)  as disc_amount,f_invoice_det.amount-(f_invoice_det.amount*\r\ndisc_per /100) as sales_amount FROM f_invoice,f_invoice_det,ledger_mast , product_mast ,company where  f_invoice_det.invoice_code = f_invoice.invoice_code and ledger_mast.ledger_code = f_invoice.ledger_code and f_invoice_det.design_code=product_mast.product_code and ifnull(status,\'N\')<>\'C\' and  f_invoice.c_code=company.c_code  and f_invoice.c_code=$(companycode) and  $(fromdate) $(todate)', 0, 0, 0, 'b/f', NULL, '', 'date(bill_date),bill_no,sno', 'asc', 1, 1, 0, 0, 'bill_date,bill_no,ledger_name', '', '', '', '', '', 0, 0, '', ''),
(800004, 'sales_register_design_design', 'Design Wise - Party Register', 'select comp_name, concat(\'Sales Register From \', DATE_FORMAT(\'$(fromdate)\',\'%d/%m/%Y\'), \' To \',DATE_FORMAT(\'$(todate)\',\'%d/%m/%Y\')),concat(\'Design:\',\'$(design)\')  from company where company.c_code=$(companycode)', 0, NULL, 'companycode', 'SELECT DATE_FORMAT(f_invoice.bill_date,\'%d/%m/%Y\') as bill_date,ledger_mast.ledger_name as ledger_name,ledger_mast.branch as place,f_invoice.bill_no bill_no, product_name,f_invoice_det.mtrs as mtrs,  f_invoice_det.pcs as pcs,f_invoice_det.rate as rate,f_invoice_det.amount as amount,f_invoice.disc_per as disc_per,round((f_invoice_det.amount*\r\ndisc_per /100),2) as disc_amount,f_invoice_det.amount-(f_invoice_det.amount*\r\ndisc_per /100) as sales_amount FROM f_invoice,f_invoice_det,ledger_mast , product_mast ,company WHERE ( f_invoice_det.invoice_code = f_invoice.invoice_code ) and (ledger_mast.ledger_code = f_invoice.ledger_code) and f_invoice_det.design_code=product_mast.product_code and ifnull(status,\'N\')<>\'C\'  and f_invoice.c_code=company.c_code and f_invoice.c_code=$(companycode)     and  $(fromdate) $(todate) $(design)', 0, 0, 0, 'b/f', NULL, '', 'date(bill_date),bill_no,sno', 'asc', 1, 1, 0, 0, 'bill_date,bill_no,ledger_name', '', '', '', '', '', 0, 0, '', ''),
(800005, 'sales_register_design_party', 'Party Wise - Design Register', 'select comp_name, concat(\'Sales Register From \', DATE_FORMAT(\'$(fromdate)\',\'%d/%m/%Y\'), \' To \',DATE_FORMAT(\'$(todate)\',\'%d/%m/%Y\')),concat(\'Party: \',\'$(ledger)\')  from company where company.c_code=$(companycode)', 0, NULL, 'companycode', 'SELECT DATE_FORMAT(f_invoice.bill_date,\'%d/%m/%Y\') as bill_date,concat(ledger_mast.ledger_name,\' \',ledger_mast.branch)as ledger_name, ledger_mast.branch as place, f_invoice.bill_no bill_no, product_name,f_invoice_det.mtrs as mtrs,  f_invoice_det.pcs as pcs,f_invoice_det.rate as rate,f_invoice_det.amount as amount,f_invoice.disc_per as disc_per,round((f_invoice_det.amount*\r\ndisc_per /100),2) as disc_amount,f_invoice_det.amount-(f_invoice_det.amount*\r\ndisc_per /100) as sales_amount FROM f_invoice,f_invoice_det,ledger_mast , product_mast ,company WHERE ( f_invoice_det.invoice_code = f_invoice.invoice_code ) and (ledger_mast.ledger_code = f_invoice.ledger_code) and f_invoice_det.design_code=product_mast.product_code  and ifnull(status,\'N\')<>\'C\' and f_invoice.c_code=company.c_code and f_invoice.c_code=$(companycode)      and  $(fromdate) $(todate) $(ledger)', 0, 0, 0, 'b/f', NULL, '', 'date(bill_date),bill_no,sno', 'desc', 1, 1, 0, 0, 'bill_date,bill_no,ledger_name', '', '', '', '', '', 0, 0, '', ''),
(800007, 'purc_register_party', 'Purchase - Vendor wise', 'select comp_name, concat(\'Purchase From \', DATE_FORMAT(\'$(fromdate)\',\'%d/%m/%Y\'), \' To \',DATE_FORMAT(\'$(todate)\',\'%d/%m/%Y\')),concat(\'Vendor: \',\'$(ledger)\')   from company where company.c_code=$(companycode)', 0, NULL, 'companycode', 'select bill_no as bill_no,DATE_FORMAT(bill_date,\'%d/%m/%Y\') bill_dt,ledger_name,branch,qty,unit_name,amount as  amount,freight,discount,cgst_amount,sgst_amount,igst_amount,total_amt  from v_purc_tax where c_code=$(companycode) and $(fromdate) $(todate) $(ledger) ', 0, 0, 0, 'b/f', NULL, '', 'date(bill_date),bill_no', 'asc', 1, 1, 0, 0, '', '', '', '', '', '', 0, 0, '', ''),
(800008, 'sales_register_summary', 'Sales Register - Overall', 'select issue_code from chemical_issue', 0, NULL, '', 'select ledger_name as ledger_name,branch, sum(total_amt) total_amt from f_invoice f1,ledger_mast l1 where f1.ledger_code=l1.ledger_code and f1.c_code<>3 and ifnull(status,\'N\')<>\'C\' and $(fromdate) $(todate) group by ledger_name,branch', 0, 0, 0, 'b/f', NULL, '', 'ledger_name', 'asc', 1, 1, 0, 0, '', '', '', '', '', '', 0, 0, '', ''),
(800010, 'Lorry Invoice', 'Lorry Invoice', 'select product_code from product_mast', 0, NULL, '', 'select prod_code,product_name,sum(v1.op_stock) op_stk,sum(received) received,sum(consumed) consumed,sum(v1.op_stock+received-consumed) cl_stk from v_chemical_stock_all v1,product_mast p1 where v1.product_code=p1.product_code   $(todate) group by product_name,prod_code', 0, 0, 0, 'b/f', NULL, '', 'product_name', 'asc', 0, 1, 0, 0, '', '', '', '', '', '', 0, 0, '', ''),
(800011, 'Sizing Set Order', 'Sizing Set Order', 'select product_code from product_mast', 0, NULL, '', 'select order_no,order_date,total_ends,ledger_name,mill_name,count_name,cone_weight,no_of_cones,dis_between_flange,no_of_back_beam,no_of_creal,set_length,no_of_sized_beam,sized_beam_reqd_date from sizing_set_order s1,ledger_mast l1,mill_mast m1,count_mast c1 where s1.ledger_code=l1.ledger_code and s1.mill_code=m1.mill_code and s1.count_code=c1.count_code', 0, 0, 0, 'b/f', NULL, '', 'order_date,order_no', 'asc', 0, 1, 0, 0, '', '', '', '', '', '', 0, 0, '', ''),
(800013, 'stock_ason_date', 'As on Date Stock Register', 'select comp_name, concat(\'Stock Register As on \', DATE_FORMAT(\'$(fromdate)\',\'%d/%m/%Y\'))  from company where company.c_code=1', 0, NULL, '', 'select product_name,prod_code,p1.product_code,min_qty,max_qty,ifnull(sum(qty),0) stk,ifnull(sum(mtrs),0) stk_mtrs,purc_rate as rate,case when unit_code=1 then round(ifnull(sum(qty),0)*purc_rate,2) else round(ifnull(sum(mtrs),0)*purc_rate,2) end as stock_value  from v_stock v1,product_mast p1 where v1.product_code=p1.product_code and $(fromdate) group by prod_code,p1.product_code,product_name,min_qty,max_qty,unit_code having ifnull(sum(qty),0)<>0 <<SF>>', 0, 0, 0, 'b/f', NULL, '', 'product_name', 'asc', 1, 0, 0, 0, 'product_name', '', '', '', '', '', 0, 0, '', ''),
(800014, 'sales_register_b2b', 'Sales Register (GSTR1) B2B', 'select comp_name, concat(\'Sales Register (GSTR1) B2B From \', DATE_FORMAT(\'$(fromdate)\',\'%d/%m/%Y\'), \' To \',DATE_FORMAT(\'$(todate)\',\'%d/%m/%Y\'))  from company where company.c_code=$(companycode)', 0, NULL, 'companycode', 'SELECT  gstin_no,ledger_name,bill_no as bill_no,DATE_FORMAT(bill_dt,\'%d/%M/%Y\')  as bill_date,total_amt,place_of_supply as state,\'N\' rev_charge,\'\' as tax_rate_applicable,\'Regular\' inv_type,\'\' ecomm_gstin,tax_perc,sale_amount,0 as cess from v_sales f1 where f1.c_code=$(companycode) and $(fromdate) $(todate)', 0, 0, 0, 'b/f', NULL, '', 'date(bill_date),bill_no', 'asc', 1, 1, 0, 0, 'bill_date,bill_no', '', '', '', '', '', 0, 0, '', ''),
(800015, 'sales_hsn_summary', 'Sales HSN Summary', 'select comp_name, concat(\'Sales Register (GSTR1) HSN Summary From \', DATE_FORMAT(\'$(fromdate)\',\'%d/%m/%Y\'), \' To \',DATE_FORMAT(\'$(todate)\',\'%d/%m/%Y\'))  from company where company.c_code=$(companycode)', 0, NULL, 'companycode', 'select hsn_code as HSN,\'Fabric\' as description, \'PCS-PIECES\' AS UQC, sum(total_qty) as total_qty,sum(taxable_value+igst_amount+sgst_amount+cgst_amount+freight+round_off) as total_value, sum(taxable_value) as taxable_value,sum(igst_amount) as igst_amount ,sum(cgst_amount) as cgst_amount,\r\nsum(sgst_amount) as sgst_amount, sum(cess) as cess \r\n from v_sales_hsn_summary v1 where v1.c_code=$(companycode) and $(fromdate) $(todate) group by hsn_code', 0, 0, 0, 'b/f', NULL, '', 'hsn', 'asc', 1, 0, 0, 0, 'hsn', '', '', '', '', '', 0, 0, '', ''),
(800016, 'purcase_register_b2b', 'Purchase Register (GSTR2) B2B', 'select comp_name, concat(\'Purchase Register (GSTR2) B2B From \', DATE_FORMAT(\'$(fromdate)\',\'%d/%m/%Y\'), \' To \',DATE_FORMAT(\'$(todate)\',\'%d/%m/%Y\'))  from company where company.c_code=$(companycode)', 0, NULL, 'companycode', 'SELECT  local_interstate,gstin_no,bill_no as bill_no,DATE_FORMAT(bill_dt,\'%d/%M/%Y\')  as bill_date,total_amt,place_of_supply as state,\'N\' rev_charge,\'Regular\' inv_type,\'\' ecomm_gstin,tax_perc,sale_amount,0 as cess from v_purchase f1  where f1.c_code=$(companycode) and $(fromdate) $(todate)', 0, 0, 0, 'b/f', NULL, '', 'local_interstate,bill_dt', 'asc', 1, 1, 0, 0, 'local_interstate', '', '', '', '', '', 0, 0, '', ''),
(800017, 'purchase_hsn_summary', 'Purchase HSN Summary', 'select comp_name, concat(\'Purchase Register (GSTR2) HSN Summary From \', DATE_FORMAT(\'$(fromdate)\',\'%d/%m/%Y\'), \' To \',DATE_FORMAT(\'$(todate)\',\'%d/%m/%Y\'))  from company where company.c_code=$(companycode)', 0, NULL, 'companycode', 'select hsn_code as HSN,\'Fabric\' as description, \'PCS-PIECES\' AS UQC, sum(total_qty) as total_qty,sum(total_value+round_off) as total_value, sum(taxable_value) as taxable_value,sum(igst_amount) as igst_amount ,sum(cgst_amount) as cgst_amount,\r\nsum(sgst_amount) as sgst_amount, sum(cess) as cess \r\n from v_purc_hsn_summary v1 where v1.c_code=$(companycode) and $(fromdate) $(todate) group by hsn_code', 0, 0, 0, 'b/f', NULL, '', 'hsn', 'asc', 1, 0, 0, 0, 'hsn', '', '', '', '', '', 0, 0, '', ''),
(800018, 'excess_stock', 'Excess Stock Register', 'select comp_name, concat(\'Stock Register As on \', DATE_FORMAT(\'$(fromdate)\',\'%d/%m/%Y\'))  from company where company.c_code=1', 0, NULL, '', 'select prod_code,product_name,p1.product_code,min_qty,max_qty, case unit_code when 1 then (select sum(qty) \r\nfrom v_stock v1 where v1.product_code=p1.product_code and $(fromdate)) -max_qty  when 2 then 0  end as  stk ,case unit_code when 2 then (select sum(mtrs) \r\nfrom v_stock v1 where v1.product_code=p1.product_code and $(fromdate)) -max_qty  when 1 then 0  end as stk_mtrs,purc_rate as rate,round((case unit_code when 1 then (select sum(qty) \r\nfrom v_stock v1 where v1.product_code=p1.product_code and $(fromdate)) -max_qty  when 2 then (select sum(mtrs) \r\nfrom v_stock v1 where v1.product_code=p1.product_code and $(fromdate)) -max_qty   end)*purc_rate ,2) as  amount  from  product_mast p1   where (case unit_code when 1 then (select sum(qty) from v_stock v1 where v1.product_code=p1.product_code and $(fromdate)) -max_qty  when 2 then 0  end >0  or case unit_code when 2 then (select sum(mtrs) from v_stock v1 where v1.product_code=p1.product_code and $(fromdate)) -max_qty  when 1 then 0  end >0) <<SF>>', 0, 0, 0, 'b/f', NULL, '', 'product_name', 'asc', 1, 0, 0, 0, 'product_name', '', '', '', '', '', 0, 0, '', ''),
(800019, 'shortage_stock', 'Shortage Stock Register', 'select comp_name, concat(\'Stock Register As on \', DATE_FORMAT(\'$(fromdate)\',\'%d/%m/%Y\'))  from company where company.c_code=1', 0, NULL, '', 'select prod_code,product_name,p1.product_code,min_qty,max_qty, case unit_code when 1 then (select sum(qty) \r\nfrom v_stock v1 where v1.product_code=p1.product_code and $(fromdate)) -min_qty  when 2 then 0  end *-1 as  stk ,case unit_code when 2 then (select sum(mtrs) \r\nfrom v_stock v1 where v1.product_code=p1.product_code and $(fromdate)) -min_qty  when 1 then 0  end *-1 as stk_mtrs,purc_rate as rate,round((case unit_code when 1 then (select sum(qty) \r\nfrom v_stock v1 where v1.product_code=p1.product_code and $(fromdate)) -min_qty  when 2 then (select sum(mtrs) \r\nfrom v_stock v1 where v1.product_code=p1.product_code and $(fromdate)) -min_qty   end)*purc_rate *-1 ,2) as  amount  from  product_mast p1 where\r\n(case unit_code when 1 then (select sum(qty) from v_stock v1 where v1.product_code=p1.product_code and $(fromdate)) -min_qty  when 2 then 0  end <0  or case unit_code when 2 then (select sum(mtrs) from v_stock v1 where v1.product_code=p1.product_code and $(fromdate)) -min_qty  when 1 then 0  end <0)', 0, 0, 0, 'b/f', NULL, '', 'product_name', 'asc', 1, 0, 0, 0, 'prod_code,product_name', '', '', '', '', '', 0, 0, '', ''),
(800020, 'purchase_register', 'Purchase Register', 'select comp_name, concat(\'Purchase Register From \', DATE_FORMAT(\'$(fromdate)\',\'%d/%m/%Y\'), \' To \',DATE_FORMAT(\'$(todate)\',\'%d/%m/%Y\')) from company where company.c_code=$(companycode)', 0, NULL, 'companycode', 'select bill_no as bill_no,DATE_FORMAT(bill_date,\'%d/%m/%Y\') bill_dt,ledger_name,branch,amount as  amount,freight,discount,cgst_amount,sgst_amount,igst_amount,total_amt  from v_purc_tax where c_code=$(companycode) and $(fromdate) $(todate)', 0, 0, 0, 'b/f', NULL, '', 'bill_date,bill_no', 'asc', 1, 1, 0, 0, '', '', '', '', '', '', 0, 0, '', ''),
(800021, 'gstr_3b', 'GSTR-3B', 'select branchname from branch_master', 0, NULL, 'fromdate,todate,companycode', 'select groupname,detail,col1,col2,col3,col4,col5,isgroup from gstr3bfinal', 0, 0, 0, 'b/f', NULL, 'text,text,text', 'groupname', 'asc', 0, 0, 0, 0, NULL, '', '', '', 'com.hiq.trade.transaction.ProcessReportData', 'groupname', 0, 0, 'isgroup', ''),
(800022, 'stock_ledger', 'Stock Ledger', 'select comp_name, concat(\'Stock Ledger From \', DATE_FORMAT(\'$(fromdate)\',\'%d/%m/%Y\'), \' To \',DATE_FORMAT(\'$(todate)\',\'%d/%m/%Y\')) from company where company.c_code=$(companycode)', 0, NULL, 'companycode,fromdateval', 'select format(@totalmtrs,0) openingmtrs,format(@totalqty,0) openingqty, DATE_FORMAT(dt,\'%d/%m/%Y\') dt,inward_no,party,format(inward_qty,0) inward_qty,format(inward_mtrs,0) inward_mtrs,format(outward_qty,0) outward_qty,format(outward_mtrs,0) outward_mtrs,format(sold_qty,0) sold_qty,format(sold_mtrs,0) sold_mtrs,purc_rate,sales_rate,disc_rate,format(@totalqty:=@totalqty+(inward_qty-outward_qty-sold_qty),0) totalqty,format(@totalmtrs:=@totalmtrs+(inward_mtrs-outward_mtrs-sold_mtrs),0) totalmtrs from v_stock_ledger v1 $var_initialize where $(fromdate) $(todate) $(design)', 0, 0, 0, 'b/f', NULL, 'int,date', 'date(dt),inward_no,sno', 'asc', 1, 0, 0, 0, '', 'totalqty,totalmtrs', 'select sum(inward_qty-outward_qty-sold_qty) totalqty,sum(inward_mtrs-outward_mtrs-sold_mtrs) totalmtrs from v_stock_ledger v1 where dt<\'$(fromdateval)\' $(design)', 'totalqty,totalmtrs', '', '', 0, 0, '', ''),
(800023, 'stock_movement_register', 'Stock Movement Register', 'select comp_name, \'Stock Movement Register\' from company where company.c_code=$(companycode)', 0, NULL, 'companycode', 'select prod_code,product_code,product_name,DATE_FORMAT(max(last_inward_date),\'%d/%m/%Y\')as last_inward_date,DATE_FORMAT(max(last_invoice_date),\'%d/%m/%Y\')as last_invoice_date,datediff(curdate(),max(last_invoice_date)) as days,max(stock_pcs) as stock_pcs,max(stock_mtrs) as stock_mtrs from v_product_movement group by prod_code,product_code,product_name having max(stock_pcs)<>0 or max(stock_mtrs) <>0', 0, 0, 0, 'b/f', NULL, '', 'prod_code', 'asc', 0, 0, 0, 0, '', '', '', '', '', '', 0, 0, '', ''),
(800024, 'mth_purchase_sales', 'Monthly Purchase/Sales', 'select comp_name, concat(\'Receipts Register From \', DATE_FORMAT(\'$(fromdate)\',\'%d/%m/%Y\'), \' To \',DATE_FORMAT(\'$(todate)\',\'%d/%m/%Y\')) from company where company.c_code=$(companycode)', 0, NULL, 'companycode', 'select m1.mth_code,m1.mth_name,m1.year,(select ifnull(sum(taxable_amt),0) \r\nfrom f_invoice_det f2,f_invoice f1 where f1.invoice_code=f2.invoice_code and ifnull(status,\'N\')<>\'C\' and (month(f1.bill_date)=m1.mth_no and year(f1.bill_date)=m1.year and f1.c_code=$(companycode) and date(bill_date)>=$(fromdate) and date(bill_date)<=$(todate))) - (select ifnull(sum(amount),0) \r\nfrom purc_sale_det f1,purc_sale f2 where f1.tran_code=f2.tran_code and tran_type=\'C\' and ifnull(status,\'N\')<>\'C\' and  (month(f1.bill_date)=m1.mth_no and year(f1.bill_date)=m1.year and f2.c_code=$(companycode) and date(bill_date)>=$(fromdate) and date(bill_date)<=$(todate)))- (select ifnull(sum(amount),0) \r\nfrom sales_ret_det f1,sales_ret f2 where f1.invoice_code=f2.invoice_code and ifnull(status,\'N\')<>\'C\' and  (month(f2.bill_date)=m1.mth_no and year(f2.bill_date)=m1.year and f2.c_code=$(companycode) and date(bill_date)>=$(fromdate) and date(bill_date)<=$(todate))) as sales_value, (select ifnull(sum(amount),0) \r\nfrom purc_sale_det f1,purc_sale f2 where f1.tran_code=f2.tran_code and tran_type=\'P\' and ifnull(status,\'N\')<>\'C\' and  (month(f1.bill_date)=m1.mth_no and year(f1.bill_date)=m1.year and f2.c_code=$(companycode) and date(bill_date)>=$(fromdate) and date(bill_date)<=$(todate))) - (select ifnull(sum(amount),0) \r\nfrom purc_sale_det f1,purc_sale f2 where f1.tran_code=f2.tran_code and tran_type=\'D\' and ifnull(status,\'N\')<>\'C\' and  (month(f1.bill_date)=m1.mth_no and year(f1.bill_date)=m1.year and f2.c_code=$(companycode) and date(bill_date)>=$(fromdate) and date(bill_date)<=$(todate))) + (select ifnull(sum(amount),0) \r\nfrom purc_inv_det p1,purc_inv p2 where p1.inv_code=p2.inv_code and ifnull(status,\'N\')<>\'C\' and (month(p2.inv_date)=m1.mth_no and year(p2.inv_date)=m1.year and p2.c_code=$(companycode) and date(inv_date)>=$(fromdate) and date(inv_date)<=$(todate) and p2.transaction_type=\'B\'))+ (select ifnull(sum(amount),0) \r\nfrom purc_inv_det p1,purc_inv p2 where p1.inv_code=p2.inv_code and ifnull(status,\'N\')<>\'C\' and (month(p2.party_inv_date)=m1.mth_no and year(p2.party_inv_date)=m1.year and p2.c_code=$(companycode) and date(party_inv_date)>=$(fromdate) and date(party_inv_date)<=$(todate) and p2.transaction_type=\'I\' and trim(party_inv_no)<>\'\')) as purc_value  from mth m1 where (select ifnull(sum(taxable_amt),0) \r\nfrom f_invoice_det f2,f_invoice f1 where f1.invoice_code=f2.invoice_code and (month(f1.bill_date)=m1.mth_no and year(f1.bill_date)=m1.year and f1.c_code=$(companycode) and date(bill_date)>=$(fromdate) and date(bill_date)<=$(todate))) <>0 group by m1.mth_code,m1.mth_name\r\n<<SF>>', 0, 0, 0, 'b/f', NULL, '', 'm1.mth_code', 'asc', 1, 1, 0, 0, 'mth_name', '', '', '', '', '', 0, 0, '', ''),
(800025, 'purc_register_summary', 'Purchase Register - Overall', 'select issue_code from chemical_issue', 0, NULL, '', 'select ledger_name,branch,sum(net_amount) total_amt from (select ledger_name as ledger_name,branch,  net_amount from\r\n purc_sale  f1,purc_sale_det f2,ledger_mast l1 where f1.tran_code=f2.tran_code and tran_type=\'P\' and f2.ledger_code=l1.ledger_code and f2.ledger_code<>85 and ifnull(status,\'N\')<>\'C\' and date(bill_date)>=$(fromdate) and date(bill_date)<=$(todate) \r\n\r\nunion all \r\n\r\nselect ledger_name as ledger_name,branch,tot from\r\n purc_inv f1,purc_inv_det f2,ledger_mast l1 where f1.inv_code=f2.inv_code and f1.ledger_code=l1.ledger_code and  ifnull(status,\'N\')<>\'C\' and date(inv_date)>=$(fromdate) and date(inv_date)<=$(todate)) a where 1=1  group by ledger_name,branch', 0, 0, 0, 'b/f', NULL, '', 'ledger_name', 'asc', 1, 1, 0, 0, '', '', '', '', '', '', 0, 0, '', ''),
(800026, 'sales_register_b2b_unregistrar', 'Sales Register (GSTR1) B2B (UnRegisterar)', 'select comp_name, concat(\'Sales Register (GSTR1) B2B From \', DATE_FORMAT(\'$(fromdate)\',\'%d/%m/%Y\'), \' To \',DATE_FORMAT(\'$(todate)\',\'%d/%m/%Y\'))  from company where company.c_code=$(companycode)', 0, NULL, 'companycode', 'SELECT  p1.place_of_supply as state, case when cgst_per>0 then cgst_per+sgst_per else igst_per end   as tax_perc,ifnull(sum(tot-discount),0) taxable_amt,ifnull(sum(cgst_amount),0) as cgst_amount,ifnull(sum(sgst_amount),0) as sgst_amount,ifnull(sum(igst_amount),0) as igst_amount,ifnull(sum(courier_charges),0) as freight,ifnull(sum(total_amt),0) as net_amount from f_invoice f1,ledger_mast l1,place_of_supply_mast p1  where f1.ledger_code=l1.ledger_code and l1.place_of_supply_code=p1.place_of_supply_code and trim(l1.gstin_no)=\'\' and ifnull(f1.status,\'N\')<>\'C\' and  f1.c_code=$(companycode) and $(fromdate) $(todate) group by p1.place_of_supply', 0, 0, 0, 'b/f', NULL, '', 'p1.place_of_supply', 'asc', 1, 1, 0, 0, 'state', '', '', '', '', '', 0, 0, '', ''),
(800027, 'sales_register_b2b_unregistrar', 'Sales Register (GSTR1) B2B (UnRegisterar) Detailed', 'select comp_name, concat(\'Sales Register (GSTR1) B2B (UnRegistrar) From \', DATE_FORMAT(\'$(fromdate)\',\'%d/%m/%Y\'), \' To \',DATE_FORMAT(\'$(todate)\',\'%d/%m/%Y\'))  from company where company.c_code=$(companycode)', 0, NULL, 'companycode', 'SELECT  DATE_FORMAT(bill_date,\'%d/%m/%Y\') as bill_date,bill_no,l1.ledger_name as supplier_name,l1.gstin_no as gstin_no,p1.place_of_supply as state, case when cgst_per>0 then cgst_per+sgst_per else igst_per end   as tax_perc,ifnull(tot-discount,0) taxable_amt,ifnull(cgst_amount,0) as cgst_amount,ifnull(sgst_amount,0) as sgst_amount,ifnull(igst_amount,0) as igst_amount,ifnull(courier_charges,0) as freight,ifnull(total_amt,0) as net_amount from f_invoice f1,ledger_mast l1,place_of_supply_mast p1  where f1.ledger_code=l1.ledger_code and l1.place_of_supply_code=p1.place_of_supply_code and trim(l1.gstin_no)=\'\' and ifnull(f1.status,\'N\')<>\'C\' and  f1.c_code=$(companycode) and $(fromdate) $(todate)', 0, 0, 0, 'b/f', NULL, '', 'date(bill_date)', 'asc', 1, 1, 0, 0, 'state', '', '', '', '', '', 0, 0, '', ''),
(800028, 'bought_note_register', 'Bought Note Register', 'select comp_name, concat(\'Bought Note Register From \', DATE_FORMAT(\'$(fromdate)\',\'%d/%m/%Y\'), \' To \',DATE_FORMAT(\'$(todate)\',\'%d/%m/%Y\')) from company where company.c_code=$(companycode)', 0, NULL, 'companycode', 'select bn_no,DATE_FORMAT(bn_date,\'%d/%m/%Y\') bn_date,ledger_name,product_name,qty,mtrs,rate,amount from bought_note p1,bought_note_det p2,ledger_mast l1,product_mast p3  where p1.bn_code=p2.bn_code and p1.ledger_code=l1.ledger_code and p2.product_code2=p3.product_code and  ifnull(status,\'N\')<>\'C\'and $(fromdate) $(todate)', 0, 0, 0, 'b/f', NULL, 'TEXT,TEXT', 'date(bn_date),bn_no', 'asc', 1, 1, 0, 0, 'bn_no,bn_date,ledger_name', '', '', '', '', '', 0, 0, '', ''),
(800029, 'bought_note_pending', 'Bought Note Pending Register', 'select comp_name, concat(\'Bought Note Pending Register As on \', DATE_FORMAT(\'$(fromdate)\',\'%d/%m/%Y\') from company where company.c_code=$(companycode)', 0, NULL, 'companycode', 'select ledger_name,ifnull(sum(amount),0) amount from bought_note p1,bought_note_det p2,ledger_mast l1 where p1.bn_code=p2.bn_code and p1.ledger_code=l1.ledger_code and ifnull(status,\'N\')<>\'C\' and p1.bn_code not in(select p2.bn_code from\r\n purc_inv p1,purc_inv_det p2 where p1.inv_code=p2.inv_code and ifnull(p1.status,\'N\')<>\'C\') group by ledger_name', 0, 0, 0, 'b/f', NULL, 'TEXT,TEXT', 'ledger_name', 'asc', 1, 1, 0, 0, 'ledger_name', '', '', '', '', '', 0, 0, '', ''),
(800030, 'purchase_inv_pending', 'Purchase Invoice Pending', 'select comp_name, concat(\'Purchase Invoice Pending Register As on \', DATE_FORMAT(\'$(fromdate)\',\'%d/%m/%Y\') from company where company.c_code=$(companycode)', 0, NULL, 'companycode', 'select inv_no,DATE_FORMAT(inv_date,\'%d/%m/%Y\') inv_date,ledger_name,ifnull(total_amount,0) amount from purc_inv p1,ledger_mast l1 where p1.ledger_code=l1.ledger_code and ifnull(status,\'N\')<>\'C\' and c_code=$(companycode) and transaction_type=\'I\' and trim(party_inv_no)=\'\'', 0, 0, 0, 'b/f', NULL, 'TEXT,TEXT', 'inv_no,inv_date', 'asc', 1, 1, 0, 0, 'inv_no,inv_date', '', '', '', '', '', 0, 0, '', ''),
(800031, 'sales_dc_pending', 'Sales DC Pending', 'select comp_name, concat(\'Sales DC Pending Register As on \', DATE_FORMAT(\'$(fromdate)\',\'%d/%m/%Y\') from company where company.c_code=$(companycode)', 0, NULL, 'companycode', 'select bill_no inv_no,DATE_FORMAT(bill_date,\'%d/%m/%Y\') inv_date,ledger_name,l1.branch,ifnull(total_amt,0) amount,comp_name from dc p1,ledger_mast l1,company c1 where p1.c_code=c1.c_code and p1.ledger_code=l1.ledger_code and ifnull(status,\'N\')<>\'C\' and p1.invoice_code not in(select f1.dc_code from f_invoice_det f1,f_invoice f2 where f1.invoice_code=f2.invoice_code and ifnull(f2.status,\'N\')<>\'C\')  $(fromdate) ', 0, 0, 0, 'b/f', NULL, 'TEXT,TEXT', 'inv_no,inv_date', 'asc', 1, 1, 0, 0, 'inv_no,inv_date', '', '', '', '', '', 0, 0, '', ''),
(800032, 'sales_order_pending', 'Pending Sales Order', 'select comp_name, concat(\'Sales Order Pending Register As on \', DATE_FORMAT(\'$(fromdate)\',\'%d/%m/%Y\') from company where company.c_code=$(companycode)', 0, NULL, 'companycode', 'select ledger_name,product_name,sum(qty) - (select ifnull(sum(pcs),0) \r\nfrom f_invoice_det f1,f_invoice f2 where f1.invoice_code=f2.invoice_code and f1.design_code=s2.product_code and f2.ledger_code=s1.ledger_code and ifnull(f2.status,\'N\')<>\'C\') qty from sale_order s1,sale_order_det s2,ledger_mast l1,product_mast P1 where s1.order_code=s2.order_code and s1.ledger_code=l1.ledger_code and s2.product_code=p1.product_code and ifnull(s1.status,\'N\')<>\'C\' group by ledger_name,product_name', 0, 0, 0, 'b/f', NULL, 'TEXT,TEXT', 'ledger_name,product_name', 'asc', 1, 1, 0, 0, 'ledger_name,product_name', '', '', '', '', '', 0, 0, '', ''),
(800033, 'purc_register_design_all', 'Design Wise - Purchase Register', 'select comp_name, concat(\'Purchase  Register From \', DATE_FORMAT(\'$(fromdate)\',\'%d/%m/%Y\'), \' To \',DATE_FORMAT(\'$(todate)\',\'%d/%m/%Y\')) from company where company.c_code=$(companycode)', 0, NULL, 'companycode', 'SELECT DATE_FORMAT(bought_note.bn_date,\'%d/%m/%Y\')  as bill_date, ledger_mast.ledger_name as ledger_name, ledger_mast.branch as place, bought_note.bn_no bill_no, product_name,bought_note_det.mtrs as mtrs,  bought_note_det.qty as pcs,bought_note_det.rate as rate,bought_note_det.amount as amount,0 as disc_per,0 as disc_amount,bought_note_det.amount  as sales_amount FROM bought_note,bought_note_det,ledger_mast , product_mast ,company where  bought_note_det.bn_code = bought_note.bn_code and ledger_mast.ledger_code = bought_note.ledger_code and bought_note_det.product_code2=product_mast.product_code and ifnull(status,\'N\')<>\'C\' and  $(fromdate) $(todate)', 0, 0, 0, 'b/f', NULL, '', 'date(bn_date),bn_no,sno', 'asc', 1, 1, 0, 0, 'bill_date,bill_no', '', '', '', '', '', 0, 0, '', ''),
(800034, 'purc_register_design_design', 'Design Wise - Vendor Register', 'select comp_name, concat(\'Purchase Register From \', DATE_FORMAT(\'$(fromdate)\',\'%d/%m/%Y\'), \' To \',DATE_FORMAT(\'$(todate)\',\'%d/%m/%Y\')),concat(\'Design:\',\'$(design)\')  from company where company.c_code=$(companycode)', 0, NULL, 'companycode', 'SELECT DATE_FORMAT(bought_note.bn_date,\'%d/%m/%Y\') as bill_date,ledger_mast.ledger_name as ledger_name,ledger_mast.branch as place,bought_note.bn_no bill_no, product_name,bought_note_det.mtrs as mtrs,  bought_note_det.qty as pcs,bought_note_det.rate as rate,bought_note_det.amount as amount,0 as disc_per,0 as disc_amount,bought_note_det.amount as sales_amount FROM bought_note,bought_note_det,ledger_mast , product_mast ,company WHERE ( bought_note_det.bn_code = bought_note.bn_code ) and (ledger_mast.ledger_code = bought_note.ledger_code) and bought_note_det.product_code2=product_mast.product_code and ifnull(status,\'N\')<>\'C\'  and   $(fromdate) $(todate) $(design)', 0, 0, 0, 'b/f', NULL, '', 'date(bill_date),bill_no,sno', 'asc', 1, 1, 0, 0, 'bill_date,bill_no,ledger_name', '', '', '', '', '', 0, 0, '', ''),
(800035, 'purc_register_design_party', 'Vendor Wise - Design Register', 'select comp_name, concat(\'Purchase Register From \', DATE_FORMAT(\'$(fromdate)\',\'%d/%m/%Y\'), \' To \',DATE_FORMAT(\'$(todate)\',\'%d/%m/%Y\')),concat(\'Party: \',\'$(ledger)\')  from company where company.c_code=$(companycode)', 0, NULL, 'companycode', 'SELECT DATE_FORMAT(bought_note.bn_date,\'%d/%m/%Y\') as bill_date,concat(ledger_mast.ledger_name,\' \',ledger_mast.branch)as ledger_name, ledger_mast.branch as place, bought_note.bn_no bill_no, product_name,bought_note_det.mtrs as mtrs,  bought_note_det.qty as pcs,bought_note_det.rate as rate,bought_note_det.amount as amount,0 as disc_per,0 as disc_amount,bought_note_det.amount as sales_amount FROM bought_note,bought_note_det,ledger_mast , product_mast ,company WHERE ( bought_note_det.bn_code = bought_note.bn_code ) and (ledger_mast.ledger_code = bought_note.ledger_code) and bought_note_det.product_code2=product_mast.product_code  and ifnull(status,\'N\')<>\'C\' and  $(fromdate) $(todate) $(ledger)', 0, 0, 0, 'b/f', NULL, '', 'date(bill_date),bill_no,sno', 'desc', 1, 1, 0, 0, 'bill_date,bill_no,ledger_name', '', '', '', '', '', 0, 0, '', ''),
(800036, 'inward_register', 'Inward Register', 'select comp_name, concat(\'Inward Register From \', DATE_FORMAT(\'$(fromdate)\',\'%d/%m/%Y\'), \' To \',DATE_FORMAT(\'$(todate)\',\'%d/%m/%Y\')) from company where company.c_code=$(companycode)', 0, NULL, 'companycode', 'select DATE_FORMAT(inward_date,\'%d/%m/%Y\') inward_date,inward_no,p2.product_code product_code,prod_code,product_name,qty,mtrs,rate from inward p1,inward_det p2,product_mast p3  where p1.inward_code=p2.inward_code and p2.product_code=p3.product_code and ifnull(status,\'N\')<>\'C\'and $(fromdate) $(todate)', 0, 0, 0, 'b/f', NULL, 'TEXT,TEXT', 'date(inward_date),inward_no,sno', 'asc', 1, 1, 0, 0, 'inward_no,inward_date', '', '', '', '', '', 0, 0, '', ''),
(800037, 'outward_register', 'Outward Register', 'select comp_name, concat(\'outward Register From \', DATE_FORMAT(\'$(fromdate)\',\'%d/%m/%Y\'), \' To \',DATE_FORMAT(\'$(todate)\',\'%d/%m/%Y\')) from company where company.c_code=$(companycode)', 0, NULL, 'companycode', 'select DATE_FORMAT(outward_date,\'%d/%m/%Y\') outward_date,outward_no,p2.product_code product_code,prod_code,product_name,qty,mtrs from outward p1,outward_det p2,product_mast p3  where p1.outward_code=p2.outward_code and p2.product_code=p3.product_code and ifnull(status,\'N\')<>\'C\'and $(fromdate) $(todate)', 0, 0, 0, 'b/f', NULL, 'TEXT,TEXT', 'date(outward_date),outward_no,sno', 'asc', 1, 1, 0, 0, 'outward_no,outward_date', '', '', '', '', '', 0, 0, '', ''),
(900004, 'Ledger', 'Ledger', 'select branchname from branch_master', 0, NULL, 'account,fromdate,todate,branch,companycode', 'select filter,vcode,vtype,vno,vdate,ledgername,branch,debit,credit,remarks from (select 1 filter,0 vcode,\'\' vdate,\'\' vtype,\'\' vno,\'Opening Balance\' ledgername,\'\' branch,case when ifnull(sum(d.vd_dramount-d.vd_cramount),0) >0 then  ifnull(sum(d.vd_dramount-d.vd_cramount),0)  else 0 end Debit,case when ifnull(sum(d.vd_cramount-d.vd_dramount),0) >0 then  ifnull(sum(d.vd_cramount-d.vd_dramount),0)  else 0 end Credit,\'\' remarks from  ledger_mast l left join view_vouchers d on d.vd_ledger_code=l.ledger_code  and d.vh_date<STR_TO_DATE(\'$(fromdate)\',\'%d/%m/%Y\') where l.ledger_code=$(account) and d.branchcode=$(companycode) union all select 2 filter,1 vcode,DATE_FORMAT(v.vh_date,\'%d/%m/%Y\') vdate,v_type vtype,v.vh_no vno,v.ledger_name  ledgername,v.branch,v.vd_dramount Debit,vd_cramount Credit,\'\' vh_remarks from view_vouchers v where v.vh_date>=STR_TO_DATE(\'$(fromdate)\',\'%d/%m/%Y\') and v.vh_date<=STR_TO_DATE(\'$(todate)\',\'%d/%m/%Y\') and v.vd_ledger_code=$(account) and v.branchcode=$(companycode)) vouchers where 1=1  ', 0, 0, 0, 'b/f', NULL, 'integer,text,text,integer,integer', 'STR_TO_DATE(vdate,\'%d/%m/%Y\') asc,filter asc,vno asc,vcode', 'asc', 1, 0, 0, 0, NULL, '', '', '', '', '', 0, 0, '', ''),
(900005, 'outstanding_register', 'Party Outstanding', 'select comp_name, concat(\'From \', DATE_FORMAT(\'$(fromdate)\',\'%d/%m/%Y\'), \' To \',DATE_FORMAT(\'$(todate)\',\'%d/%m/%Y\')) from company', 0, NULL, 'companycode', 'select DATE_FORMAT(bill_date,\'%d/%m/%Y\') bill_date,bill_no,ledger_name as ledger_name,branch,ifnull(sum(total_amt-paid_amount-discount),0) as amount,datediff(curdate(),bill_date) as days from v_receivable,ledger_mast where v_receivable.ledger_code=ledger_mast.ledger_code  and c_code= $(companycode) and  $(fromdate) group by bill_date,bill_no,ledger_name,branch having ifnull(sum(total_amt-paid_amount-discount),0)<>0 <<SF>>', 0, 0, 0, 'b/f', NULL, '', 'date(bill_date),CAST(bill_no AS decimal(10,0))', 'asc', 1, 1, 0, 0, 'bill_no', '', '', '', '', '', 0, 0, '', ''),
(900006, 'outstanding_register_party', 'Outstanding Register - Party', 'select comp_name, concat(\'From \', DATE_FORMAT(\'$(fromdate)\',\'%d/%m/%Y\'), \' To \',DATE_FORMAT(\'$(todate)\',\'%d/%m/%Y\')),concat(\' \',\'\') from company  where company.c_code=$(companycode) ', 0, NULL, 'companycode', 'select DATE_FORMAT(bill_date,\'%d/%m/%Y\') bill_date,bill_no,ledger_name,ifnull(sum(amount-paid-dis),0) as amount,datediff(curdate(),bill_date) as days from v_receivable,ledger_mast where v_receivable.ledger_code=ledger_mast.ledger_code  and c_code= $(companycode) and  $(fromdate) $(todate) $(ledger) group by bill_date,bill_no,ledger_name having ifnull(sum(amount-paid-dis),0)>0', 0, 0, 0, 'b/f', NULL, '', 'date(bill_date),CAST(bill_no AS decimal(10,0))', 'asc', 1, 1, 0, 0, 'bill_no', '', '', '', '', '', 0, 0, '', ''),
(900007, 'outstanding_register_agent', 'Oustanding Register - For Agent', 'select comp_name, concat(\'From \', DATE_FORMAT(\'$(fromdate)\',\'%d/%m/%Y\'), \' To \',DATE_FORMAT(\'$(todate)\',\'%d/%m/%Y\')),concat(\'Agent:\',\'$(ledger)\') from company', 0, NULL, 'companycode', 'select DATE_FORMAT(bill_date,\'%d/%m/%Y\') bill_date,bill_no,ledger_name,ifnull(sum(amount-paid-dis),0) as amount,datediff(curdate(),bill_date) as days from v_receivable,ledger_mast where v_receivable.ledger_code=ledger_mast.ledger_code  and c_code= $(companycode) and  $(fromdate) $(todate) $(ledger) group by bill_date,bill_no,ledger_name having ifnull(sum(amount-paid-dis),0)>0', 0, 0, 0, 'b/f', NULL, '', 'date(bill_date),CAST(bill_no AS decimal(10,0))', 'asc', 1, 1, 0, 0, 'bill_no', '', '', '', '', '', 0, 0, '', ''),
(900008, 'outstanding_register_summary', 'Outstanding Register - Summary', 'select comp_name, concat(\'From \', DATE_FORMAT(\'$(fromdate)\',\'%d/%m/%Y\'), \' To \',DATE_FORMAT(\'$(todate)\',\'%d/%m/%Y\')) from company', 0, NULL, 'companycode', 'select ledger_name,ifnull(sum(amount-paid-dis),0) as amount from v_receivable,ledger_mast where v_receivable.ledger_code=ledger_mast.ledger_code  and c_code= $(companycode) and  $(fromdate) $(todate) $(ledger) group by  ledger_name having ifnull(sum(amount-paid-dis),0)>0', 0, 0, 0, 'b/f', NULL, '', 'ledger_name', 'asc', 1, 1, 0, 0, 'ledger_name', '', '', '', '', '', 0, 0, '', ''),
(900021, 'trial_balance', 'Trial Balance', 'select comp_name, concat(\'From \', DATE_FORMAT(\'$(fromdate)\',\'%d/%m/%Y\'), \' To \',DATE_FORMAT(\'$(todate)\',\'%d/%m/%Y\')) from company', 0, '', 'companycode', 'select group_name,l1.ledger_name as ledger_name,l1.branch branch,case when ifnull(sum(vd_dramount-vd_cramount),0)>0 then ifnull(sum(vd_dramount-vd_cramount),0) else 0 end as debit, \r\ncase when ifnull(sum(vd_dramount-vd_cramount),0)<0 then ifnull(sum(vd_dramount-vd_cramount),0)*-1  else 0 end as credit from view_vouchers v1, ledger_mast l1,group_mast g1 where v1.vd_ledger_code=l1.ledger_code and l1.group_code=g1.group_code and $(fromdate) and branchcode=$(companycode) group by l1.ledger_name,l1.branch, group_name having ifnull(sum(vd_dramount-vd_cramount),0)<>0 ', 0, 0, 0, 'b/f', NULL, '', 'group_name,ledger_name,branch', 'asc', 1, 1, 0, 0, 'group_name', '', '', '', '', '', 0, 0, '', ''),
(900022, 'outstanding_register_supplier', 'Vendor Outstanding', 'select comp_name, concat(\'From \', DATE_FORMAT(\'$(fromdate)\',\'%d/%m/%Y\'), \' To \',DATE_FORMAT(\'$(todate)\',\'%d/%m/%Y\')) from company', 0, NULL, 'companycode', 'select DATE_FORMAT(bill_date,\'%d/%m/%Y\') bill_date,bill_no,ledger_name as ledger_name,branch,ifnull(sum(total_amt-paid_amount-discount),0) as amount,datediff(curdate(),bill_date) as days from v_payable,ledger_mast where v_payable.ledger_code=ledger_mast.ledger_code  and c_code= $(companycode) and  $(fromdate) group by bill_date,bill_no,ledger_name,branch having ifnull(sum(total_amt-paid_amount-discount),0)<>0 <<SF>>', 0, 0, 0, 'b/f', NULL, '', 'date(bill_date),CAST(bill_no AS decimal(10,0))', 'asc', 1, 1, 0, 0, 'bill_no', '', '', '', '', '', 0, 0, '', ''),
(900023, 'receipts_register', 'Receipts Register', 'select comp_name, concat(\'Receipts Register From \', DATE_FORMAT(\'$(fromdate)\',\'%d/%m/%Y\'), \' To \',DATE_FORMAT(\'$(todate)\',\'%d/%m/%Y\')) from company where company.c_code=$(companycode)', 0, NULL, 'companycode', 'select DATE_FORMAT(rece_date,\'%d/%m/%Y\') rece_date,rece_no,ledger_name,branch,bill_no,DATE_FORMAT(bill_date,\'%d/%m/%Y\')bill_date,datediff(rece_date,bill_date) as days,r2.paid_amount amount,r2.discount,cheque_no,DATE_FORMAT(cheque_date,\'%d/%m/%Y\')cheque_date,narration from rece_mast r1,rece_det r2,ledger_mast l1 where r1.rece_code=r2.rece_code and r1.party_code=l1.ledger_code and is_paid=\'true\'and r1.c_code=$(companycode) and $(fromdate) $(todate)', 0, 0, 0, 'b/f', NULL, '', 'date(rece_date),rece_no,ledger_name,branch', 'asc', 1, 1, 0, 0, 'rece_date,rece_no,ledger_name,branch', '', '', '', '', '', 0, 0, '', '');
INSERT INTO `report_hdr` (`report_id`, `report_name`, `report_title`, `header_query`, `opening_balance`, `openbal_query`, `parameters`, `report_query`, `brought_forward`, `print_closing`, `title_for_all`, `brought_fwdtext`, `bf_column`, `param_types`, `default_sort`, `default_sort_order`, `footer_columns`, `report_pdf_paper`, `report_pdf_orient`, `report_record_lines`, `report_key_columns`, `cum_balance_var`, `cum_op_balance_query`, `cum_balance_fields`, `report_process_class`, `column_group`, `group_sum`, `page_balance`, `group_filter_column`, `coloumn_name`) VALUES
(900024, 'receipts_register_party', 'Receipts Register - For Party', 'select comp_name, concat(\'Receipts Register From \', DATE_FORMAT(\'$(fromdate)\',\'%d/%m/%Y\'), \' To \',DATE_FORMAT(\'$(todate)\',\'%d/%m/%Y\')),concat(\'Party: \',\'$(ledger)\')  from company where company.c_code=$(companycode)', 0, NULL, 'companycode', 'select DATE_FORMAT(rece_date,\'%d/%m/%Y\') rece_date,rece_no,ledger_name,bill_no,DATE_FORMAT(bill_date,\'%d/%m/%Y\')bill_date,r2.paid_amount amount,cheque_no,DATE_FORMAT(cheque_date,\'%d/%m/%Y\')cheque_date,narration from rece_mast r1,rece_det r2,ledger_mast l1 where r1.rece_code=r2.rece_code and r1.party_code=l1.ledger_code and is_paid=\'true\' and r1.c_code=$(companycode) and $(fromdate) $(todate) $(ledger)', 0, 0, 0, 'b/f', NULL, '', 'date(rece_date),rece_no', 'asc', 1, 1, 0, 0, 'rece_date,rece_no', '', '', '', '', '', 0, 0, '', ''),
(900025, 'receipts_register_bank', 'Receipts Register - For Bank', 'select comp_name, concat(\'Receipts Register From \', DATE_FORMAT(\'$(fromdate)\',\'%d/%m/%Y\'), \' To \',DATE_FORMAT(\'$(todate)\',\'%d/%m/%Y\')),concat(\'Party: \',\'$(ledger)\')  from company where company.c_code=$(companycode)', 0, NULL, 'companycode', 'select DATE_FORMAT(rece_date,\'%d/%m/%Y\') rece_date,rece_no,ledger_name,branch,bill_no,DATE_FORMAT(bill_date,\'%d/%m/%Y\')bill_date,r2.paid_amount amount,cheque_no,DATE_FORMAT(cheque_date,\'%d/%m/%Y\')cheque_date,narration,r1.amount as tot_amt from rece_mast r1,rece_det r2,ledger_mast l1 where r1.rece_code=r2.rece_code and r1.party_code=l1.ledger_code and is_paid=\'true\' and r1.c_code=$(companycode) and $(fromdate) $(todate) $(ledger)', 0, 0, 0, 'b/f', NULL, '', 'date(rece_date),rece_no,ledger_name,branch', 'asc', 1, 1, 0, 0, 'rece_date,rece_no,ledger_name,branch', '', '', '', '', '', 0, 0, '', ''),
(900026, 'Trial Balance', 'Trial Balance', 'select branchname from branch_master', 0, NULL, 'fromdate,todate,companycode', 'select groupname,ledgername,branchname,debit,credit,ledgercode,isgroup from trialbalancefinal', 0, 0, 0, 'b/f', NULL, 'text,text,text', 'groupname ,ledgername,branchname  asc,isgroup', 'desc', 1, 0, 0, 0, NULL, '', '', '', 'com.hiq.trade.transaction.ProcessReportData', 'groupname', 1, 0, 'isgroup', ''),
(900027, 'Profit & Loss', 'Trading, Profit & Loss', 'select branchname from branch_master', 0, NULL, 'fromdate,todate,companycode,reptype', 'select exgroupname,exledgername,case when exgroup=0 then examount else \'\' end exledgeramount,case when exgroup>0 then examount else \'\' end exgroupamount,exord,exrowtype,exgroup,ingroupname,inledgername,case when ingroup=0 then inamount else \'\' end inledgeramount,case when ingroup>0 then inamount else \'\' end ingroupamount,inord,inrowtype,ingroup from profitandlossfinal', 0, 0, 0, 'b/f', NULL, 'date,date,int,text', 'sno', 'asc', 0, 0, 0, 0, NULL, '', '', '', 'com.hiq.trade.transaction.ProcessReportData', '', 0, 0, '', ''),
(900028, 'Balance Sheet', 'Balance Sheet', 'select branchname from branch_master', 0, NULL, 'fromdate,todate,companycode,reptype', 'select lgroupname,lledgername,lbranch,lamount,ldrcr,lord,lrowtype,lgroup,agroupname,aledgername,abranch,aamount,adrcr,aord,arowtype,agroup from balancesheetfinal', 0, 0, 0, 'b/f', NULL, 'text,text,text,text', 'sno', 'asc', 0, 0, 0, 0, NULL, '', '', '', 'com.hiq.trade.transaction.ProcessReportData', '', 0, 0, '', ''),
(900029, 'outstanding_register_party', 'Party Outstanding Slip', 'select comp_name, concat(\'From \', DATE_FORMAT(\'$(fromdate)\',\'%d/%m/%Y\'), \' To \',DATE_FORMAT(\'$(todate)\',\'%d/%m/%Y\')) from company', 0, NULL, 'companycode', 'select DATE_FORMAT(bill_date,\'%d/%m/%Y\') bill_date,bill_no,ledger_name as ledger_name,branch,ifnull(sum(total_amt-paid_amount-discount),0) as amount,datediff(curdate(),bill_date) as days from v_receivable,ledger_mast where v_receivable.ledger_code=ledger_mast.ledger_code  and c_code= $(companycode) $(fromdate) $(todate) $(ledger)\r\n group by bill_date,bill_no,v_receivable.ledger_code,ledger_name,branch having ifnull(sum(total_amt-paid_amount-discount),0)<>0 <<SF>>\r\n', 0, 0, 0, 'b/f', NULL, '', 'date(bill_date),CAST(bill_no AS decimal(10,0))', 'asc', 1, 1, 0, 0, 'bill_no', '', '', '', '', '', 0, 0, '', ''),
(900030, 'outstanding_register_supplier1', 'Vendor Outstanding Slip', 'select comp_name, concat(\'From \', DATE_FORMAT(\'$(fromdate)\',\'%d/%m/%Y\'), \' To \',DATE_FORMAT(\'$(todate)\',\'%d/%m/%Y\')) from company', 0, NULL, 'companycode', '\r\nselect DATE_FORMAT(bill_date,\'%d/%m/%Y\') bill_date,bill_no,ledger_name as ledger_name,branch,ifnull(sum(total_amt-paid_amount-discount),0) as amount,datediff(curdate(),bill_date) as days from v_payable,ledger_mast where v_payable.ledger_code=ledger_mast.ledger_code  and c_code= $(companycode) $(fromdate) $(todate) $(ledger)\r\n group by bill_date,bill_no,v_payable.ledger_code,ledger_name,branch having ifnull(sum(total_amt-paid_amount-discount),0)<>0 <<SF>>', 0, 0, 0, 'b/f', NULL, '', 'date(bill_date),CAST(bill_no AS decimal(10,0))', 'asc', 1, 1, 0, 0, 'bill_no', '', '', '', '', '', 0, 0, '', ''),
(900031, 'Daybook', 'Daybook', 'select branchname from branch_master', 0, NULL, 'fromdate,todate,companycode', 'select filter,vcode,vtype,vno,vdate,ledgername,branch,debit,credit,remarks from (select 1 filter,0 vcode,\'\' vdate,\'\' vtype,\'\' vno,\'Opening Balance\' ledgername,\'\' branch,case when ifnull(sum(d.vd_dramount-d.vd_cramount),0) >0 then  ifnull(sum(d.vd_dramount-d.vd_cramount),0)  else 0 end Debit,case when ifnull(sum(d.vd_cramount-d.vd_dramount),0) >0 then  ifnull(sum(d.vd_cramount-d.vd_dramount),0)  else 0 end Credit,\'\' remarks from   view_vouchers d where d.vd_ledger_code=1  and date(d.vh_date)<date(\'$(fromdate)\') and  d.branchcode=$(companycode) union all select 2 filter,1 vcode,DATE_FORMAT(v.vh_date,\'%d/%m/%Y\') vdate,v_type vtype,v.vh_no vno,v.ledger_name  ledgername,v.branch,v.vd_dramount Debit,vd_cramount Credit,\'\' vh_remarks from v_daybook v where date(v.vh_date)>=date(\'$(fromdate)\') and date(v.vh_date)<=date(\'$(todate)\') and v.branchcode=$(companycode)) vouchers where 1=1  ', 0, 0, 0, 'b/f', NULL, 'date,date,int', 'STR_TO_DATE(vdate,\'%d/%m/%Y\') asc,vtype,vno asc,debit desc,credit', 'desc', 1, 0, 0, 0, 'vdate,vtype,vno', '', '', '', '', '', 0, 0, '', ''),
(900032, 'ageing_outstanding_register', 'Party (Age wise) Outstanding', 'select comp_name, concat(\'From \', DATE_FORMAT(\'$(fromdate)\',\'%d/%m/%Y\'), \' To \',DATE_FORMAT(\'$(todate)\',\'%d/%m/%Y\')) from company', 0, NULL, 'companycode', 'select DATE_FORMAT(bill_date,\'%d/%m/%Y\') bill_date,bill_no,ledger_name as ledger_name,branch,datediff(curdate(),bill_date) as days ,case when datediff(curdate(),bill_date)>=0 and datediff(curdate(),bill_date)<=30 then ifnull(sum(total_amt-paid_amount-discount),0) else 0 end as amount_0_30, case when datediff(curdate(),bill_date)>=31 and datediff(curdate(),bill_date)<=60 then ifnull(sum(total_amt-paid_amount-discount),0) else 0 end as amount_31_60, case when datediff(curdate(),bill_date)>=61 and datediff(curdate(),bill_date)<=90 then ifnull(sum(total_amt-paid_amount-discount),0) else 0 end as amount_61_90, case when datediff(curdate(),bill_date)>=91 and datediff(curdate(),bill_date)<=120 then ifnull(sum(total_amt-paid_amount-discount),0) else 0 end as amount_91_120, case when datediff(curdate(),bill_date)>=121 and datediff(curdate(),bill_date)<=150 then ifnull(sum(total_amt-paid_amount-discount),0) else 0 end as amount_121_150, case when datediff(curdate(),bill_date)>=151 and datediff(curdate(),bill_date)<=180 then ifnull(sum(total_amt-paid_amount-discount),0) else 0 end as amount_151_180, case when datediff(curdate(),bill_date)>=181 then ifnull(sum(total_amt-paid_amount-discount),0) else 0 end as amount_181  from v_receivable,ledger_mast where v_receivable.ledger_code=ledger_mast.ledger_code  and c_code= $(companycode) and  $(fromdate) group by bill_date,bill_no,ledger_name,branch having ifnull(sum(total_amt-paid_amount-discount),0)<>0 <<SF>>', 0, 0, 0, 'b/f', NULL, '', 'date(bill_date),CAST(bill_no AS decimal(10,0))', 'asc', 1, 1, 0, 0, 'bill_no', '', '', '', '', '', 0, 0, '', ''),
(900033, 'ageing_outstanding_register', 'Vendor(Age wise) Outstanding', 'select comp_name, concat(\'From \', DATE_FORMAT(\'$(fromdate)\',\'%d/%m/%Y\'), \' To \',DATE_FORMAT(\'$(todate)\',\'%d/%m/%Y\')) from company', 0, NULL, 'companycode', 'select DATE_FORMAT(bill_date,\'%d/%m/%Y\') bill_date,bill_no,ledger_name as ledger_name,branch,datediff(curdate(),bill_date) as days ,case when datediff(curdate(),bill_date)>=0 and datediff(curdate(),bill_date)<=30 then ifnull(sum(total_amt-paid_amount-discount),0) else 0 end as amount_0_30, case when datediff(curdate(),bill_date)>=31 and datediff(curdate(),bill_date)<=60 then ifnull(sum(total_amt-paid_amount-discount),0) else 0 end as amount_31_60, case when datediff(curdate(),bill_date)>=61 and datediff(curdate(),bill_date)<=90 then ifnull(sum(total_amt-paid_amount-discount),0) else 0 end as amount_61_90, case when datediff(curdate(),bill_date)>=91 and datediff(curdate(),bill_date)<=120 then ifnull(sum(total_amt-paid_amount-discount),0) else 0 end as amount_91_120, case when datediff(curdate(),bill_date)>=121 and datediff(curdate(),bill_date)<=150 then ifnull(sum(total_amt-paid_amount-discount),0) else 0 end as amount_121_150, case when datediff(curdate(),bill_date)>=151 and datediff(curdate(),bill_date)<=180 then ifnull(sum(total_amt-paid_amount-discount),0) else 0 end as amount_151_180, case when datediff(curdate(),bill_date)>=181 then ifnull(sum(total_amt-paid_amount-discount),0) else 0 end as amount_181  from v_payable,ledger_mast where v_payable.ledger_code=ledger_mast.ledger_code  and c_code= $(companycode) and  $(fromdate) group by bill_date,bill_no,ledger_name,branch having ifnull(sum(total_amt-paid_amount-discount),0)<>0 <<SF>>', 0, 0, 0, 'b/f', NULL, '', 'date(bill_date),CAST(bill_no AS decimal(10,0))', 'asc', 1, 1, 0, 0, 'bill_no', '', '', '', '', '', 0, 0, '', ''),
(900034, 'neg_cash_balance', 'Negative Cash Balance', 'select comp_name, concat(\'Negative Cash Balance From \', DATE_FORMAT(\'$(fromdate)\',\'%d/%m/%Y\'), \' To \',DATE_FORMAT(\'$(todate)\',\'%d/%m/%Y\')) from company where company.c_code=$(companycode)', 0, NULL, 'companycode', 'select distinct DATE_FORMAT(vh_date,\'%d/%m/%Y\') dt,(select ifnull(sum(vd_dramount-vd_cramount),0) \r\nfrom view_vouchers v1 where v1.vd_ledger_code=1 and branchcode=$(companycode) and date(v1.vh_date)<=date(v2.vh_date)) as balance from \r\nview_vouchers v2 where $(fromdate) $(todate)  and (select ifnull(sum(vd_dramount-vd_cramount),0) \r\nfrom view_vouchers v1 where v1.vd_ledger_code=1 and branchcode=$(companycode) and date(v1.vh_date)<=date(v2.vh_date))<0', 0, 0, 0, 'b/f', NULL, '', 'vh_date', 'asc', 0, 1, 0, 0, '', '', '', '', '', '', 0, 0, '', ''),
(910001, 'roles', 'Roles', 'select branchname from branch_master', 0, NULL, '', 'select a.role_name,a.role_id,b.role_name parentname,b.role_id parentid from role_master a inner join \n\nrole_master b on a.parent_role=b.role_id ', 0, 0, 0, 'b/f', '', '', 'role_name', 'asc', 0, 0, 0, NULL, '', '', '', '', '', '', 0, 0, '', ''),
(910002, 'employees', 'Employees', 'select branchname from branch_master', 0, NULL, '', 'SELECT \n\na.em_code,a.em_name,a.em_address1,a.em_address2,a.em_city,a.em_email,a.em_mobile,a.em_phone,a.em_user_name,a.em_type,a.em_status,u.user_name,u.user_pass,u.role_id,r.role_name,bm.branchname,ud.udb_branchcode FROM employee_master a inner join users u on a.em_user_name=u.user_name inner join role_master r on u.role_id=r.role_id inner \n\njoin user_default_branch ud on a.em_user_name=ud.udb_userid inner join branch_master bm on bm.branchcode=ud.udb_branchcode ', 0, 0, 0, 'b/f', '', '', 'em_name', 'asc', 0, 0, 0, NULL, '', '', '', '', '', '', 0, 0, '', '');
