INSERT INTO `screenloadqueries` (`slqid`, `querysource`, `queryparam`, `datagroup`, `dataarray`, `screencode`, `queryorder`) VALUES
(0, NULL, NULL, NULL, NULL, NULL, NULL),
(18, 'select group_mast.group_code as group_code,group_mast.group_name as group_name,group_mast.under_code as under_code,g1.group_name as sub_group_name,group_mast.acc_type as acc_type ,group_mast.op_stock as op_stock,group_mast.ord as ord from group_mast,group_mast g1 where group_mast.under_code=g1.group_code and group_mast.group_code=?', 'code', 1, 0, 100005, 0),
(19, 'select ledger_code code,ledger_name,ledger_mast.group_code as group_code,group_name,op_dr_bal,op_cr_bal,addr1,addr2,addr3,place,pin_no,ph_no,cell_no,email_id,website,tin_no,cst_no,pan_no,local_interstate,gstin_no,branch,ref_by,transport,transport_code,state_code,note,s_ledger_name,s_addr1,s_addr2,s_addr3,s_place,s_gstin_no,s_state_code,ledger_mast.place_of_supply_code,(select place_of_supply from place_of_supply_mast p1 where p1.place_of_supply_code=ledger_mast.place_of_supply_code) as place_of_supply,ifnull(main_ledger_code,0) as main_ledger_code,(select ledger_name from ledger_mast l5 where l5.ledger_code=ledger_mast.main_ledger_code) as main_ledger_name,(select branch from ledger_mast l5 where l5.ledger_code=ledger_mast.main_ledger_code) as main_branch, order_by as ordered_by,bill_disc_per as disc_per,spl_disc_per,aadi_disc_per,s_ph_no from ledger_mast,group_mast where ledger_mast.group_code=group_mast.group_code and  ledger_code=?', 'code', 2, 0, 100006, 0),
(20, 'select sub_ledger_code,sub_ledger_name,ledger_code,(select ledger_name from ledger_mast l1 where l1.ledger_code=sub_ledger_mast.ledger_code) as ledger_name,sl_type from sub_ledger_mast where sub_ledger_code=?', 'code', 3, 0, 100007, 0),
(21, 'select narration_code,narration from narration_mast where narration_code=?', 'code', 4, 0, 100008, 0),
(22, 'select jou_type_code,jou_type from jou_type_mast where jou_type_code=?', 'code', 5, 0, 100009, 0),
(23, 'select forms_code,forms_name from forms_mast where forms_code=?', 'code', 23, 0, 100026, 0),
(24, 'select transport_code code,transport_name from transport_mast where transport_code=?', 'code', 6, 0, 100010, 0),
(25, 'select bank_name from bank_mast where bank_code=?', 'code', 7, 0, 100011, 0),
(27, 'select place_of_supply_code code,place_of_supply from place_of_supply_mast where place_of_supply_code=?', 'code', 9, 0, 100013, 0),
(28, 'select payment_terms_code,payment_terms from payment_terms_mast where payment_terms_code=?', 'code', 10, 0, 100014, 0),
(29, 'select shipment_method_code,shipment_method,description from shipment_method where shipment_method_code=?', 'code', 11, 0, 100015, 0),
(30, 'select group_code,group_name from country_group_mast where group_code=?', 'code', 12, 0, 100016, 0),
(31, 'select country_code,country_name,curr_code,(select curr_name from curr_mast c1 where c1.curr_code=country_mast.curr_code) as curr_name,ecg_group_code,(select group_name from country_group_mast c2 where c2.group_code=country_mast.ecg_group_code) as ecg_group_name \n from country_mast where country_code=?', 'code', 13, 0, 100017, 0),
