(35, 'select product_group_code code,product_group_name from product_group_mast where product_group_code=?', 'code', 17, 0, 100021, 0),
(36, 'select unit_code,unit_name from unit_mast where unit_code=?', 'code', 18, 0, 100022, 0),
(37, 'select prod_code,product_name,alias_name,unit_code,(select unit_name from unit_mast u1 where u1.unit_code=product_mast.unit_code) as unit_name,min_qty,max_qty,product_type,description,grade,grade_desc,comm_code,capital_goods,purc_rate_limit,op_stock,op_rate,2nd_line,3rd_line,4th_line,hsn_code,hsn_mast_code,purc_rate,product_code from product_mast where product_code=?', 'code', 19, 0, 100023, 0),
(38, 'select packing_type_code,packing_type_name,packing_value,packing_description from packing_type where packing_type_code=?', 'code', 20, 0, 100024, 0),
(39, 'select count_code code,count_name,count_value,count_mast.count_type_code,count_type from count_mast,count_type_mast where count_mast.count_type_code=count_type_mast.count_type_code and count_code=?', 'code', 24, 0, 100027, 0),
(41, 'select design_code code,design_no,description from design_mast where design_code=?', 'code', 26, 0, 100029, 0),
