(44, 'select dept_code code,dept_name from weaving_dept where dept_code=?', 'code', 31, 0, 100033, 0),
(45, 'select loom_code code,loom_no,loom_type_mast.loom_type_code,loom_type from loom_mast,loom_type_mast where loom_mast.loom_type_code=loom_type_mast.loom_type_code and loom_code=?', 'code', 32, 0, 100034, 0),
(46, 'select loom_type_code code,loom_type from loom_type_mast where loom_type_code=?', 'code', 29, 0, 100032, NULL),
(300, 'select g.gir_code code,g.gir_type girtype,g.gir_prefix_code girprefix,g.gir_no girno,DATE_FORMAT(g.gir_date,\'%d/%m/%Y\') girdate,g.ledger_code suppliercode,l.ledger_name suppliername, g.addr1 address1,g.addr2 address2,g.addr3 address3,g.gir_mode mode,g.invoice_no invno,DATE_FORMAT(g.invoice_date,\'%d/%m/%Y\') invdate,lorry_no vide,g.payment_against_gir billtype, \'\' despatchedto,\'\' cashparty from gir_mast g  inner join ledger_mast l on g.ledger_code=l.ledger_code where g.gir_code=?', 'code', 1, 0, 600001, 0),
(301, 'select g.product_code productcode,p.product_name productname,g.vehicle_no vehicleno,g.qty_recd recdqty,g.qty_accepted,g.billed_qty billqty,g.godown_code godowncode,ifnull(d.godown_name,\'\') godownname,g.remarks,g.sno,\'\' indentno,0 indentcode,u.unit_name unitname,p.unit_code unitcode from gir_det g inner join product_mast p on g.product_code=p.product_code inner join unit_mast u on u.unit_code=p.unit_code left join godown_mast d on d.godown_code=g.godown_code where g.gir_code=?', 'code', 2, 1, 600001, 1),
(302, 'select vou_no,tran_type,DATE_FORMAT(entry_date,\'%d/%m/%Y\') entry_date,exp_ledger_code,(select l1.ledger_name from ledger_mast l1 where l1.ledger_code=purc_sale.exp_ledger_code) as exp_ledger_name,notes,tran_code code from purc_sale where ifnull(status,\'N\')<>\'C\' and  tran_code=?', 'code', 1, 0, 600002, 0),
(303, 'select tran_code code,DATE_FORMAT(bill_date,\'%d/%m/%Y\') bill_date,bill_no,p1.ledger_code ledger_code,hsn_code,local_interstate,ledger_name,branch,cgst_amount,sgst_amount,igst_amount,freight,discount,amount,net_amount,gst_per,qty,round_off,unit_code,unit_name from purc_sale_det p1,ledger_mast l1 where p1.ledger_code=l1.ledger_code and  p1.tran_code=? order by sno', 'code', 2, 1, 600002, 1),
(305, 'select s.sales_code code,s.sales_type dctype,s.bill_no dcno,DATE_FORMAT(s.bill_date,\'%d/%m/%Y\') dcdate,s.ledger_code customercode,l.ledger_name customername,t.tax_name taxname,s.tax_code taxcode,t.tax_type taxtype,t.vat_type vattype,s.po_code posno,s.po_no pono,tr.ledger_name transporter,s.transport_code transportercode,s.vehicle_no lorryno,s.lr_no lrno,DATE_FORMAT(s.lr_date,\'%d/%m/%Y\') lrdate,s.freight,s.st_on_freight stperc,s.st_amt_on_freight stamount,s.net_amount billamount,s.det_total detamount,s.vat_cst taxtype,s.det2_total det2amount,s.despatched_to despatchedto,s.export_invoice_code expinvcode,s.stock_transfer stocktransfer,s.freight_terms freightpaid from sales s inner join ledger_mast l on s.ledger_code=l.ledger_code inner join tax_code t on s.tax_code=t.tax_code left join ledger_mast tr on tr.ledger_code=s.transport_code where s.sales_code=?', 'code', 1, 0, 600030, 0),
(306, 'select s.sno,s.product_code productcode,p.product_name productname,s.packing_type_code packtypecode,pk.packing_type_name packtype,s.pack_type packingvalue,s.packs packages,s.qty totalqty,s.rate,s.amount,s.tax_per taxperc,s.tax_amt taxamt,s.tot_amt netamount,s.remarks remarks from sales sm inner join  sales_det s on s.sales_code=sm.sales_code inner join product_mast p on s.product_code=p.product_code inner join packing_type pk on pk.packing_type_code=s.packing_type_code Where sm.sales_code=?', 'code', 2, 1, 600030, 1),
(307, 'select s.ledger_code,ifnull(l.ledger_name,\'Not Available\') description,s.perc,s.amount taxamount,s.cr_dr,s.basic_ledger_code,s.basic_others,s.col_type from sales_det2 s  left join ledger_mast l on s.ledger_code=l.ledger_code where s.sales_code=?', 'code', 3, 1, 600030, 2),
(308, 'select s.sales_code code,s.sales_type saletype,s.bill_no billno,DATE_FORMAT(s.bill_date,\'%d/%m/%Y\') billdate,s.ledger_code,l.ledger_name customername,s.tax_code taxcode,t.tax_name taxname,t.tax_type taxtype,t.vat_type vattype,s.dc_code dccode,DATE_FORMAT(s.dc_date,\'%d/%m/%Y\') dcdate,s.po_code posno,s.po_no pono,s.doc_through documentsthrocode,d.docu_through_name documentsthro,DATE_FORMAT(time_of_inv,\'%d/%m/%Y %h:%i %p\') issuedatetime,DATE_FORMAT(time_of_rem,\'%d/%m/%Y %h:%i %p\') removedatetime,s.transport_code transportercode,tr.ledger_name transporter,s.vehicle_no lorryno,lr_no lrno,DATE_FORMAT(lr_date,\'%d/%m/%Y\') lrdate,s.freight,s.st_on_freight stperc,s.st_amt_on_freight stamount,s.net_amount billamount,s.det_total detamount,s.det2_total det2amount,despatched_to despatchedto,s.export_invoice_code expinvcode,s.dc_nos dcnos,s.lorry_nos lorrynos,s.lr_nos lrnos,s.stock_transfer stocktransfer,s.export_description consigndesc,s.supple supplementary,s.ret_gir_code gircode,g.gir_no girno,s.consignee_ledger_code consigneecode,cl.ledger_name consignee,s.freight_terms freightpaid from sales s inner join ledger_mast l on s.ledger_code=l.ledger_code inner join tax_code t on s.tax_code=t.tax_code left join ledger_mast tr on tr.ledger_code=s.transport_code left join docu_through_mast d on s.doc_through=d.docu_through_code left join gir_mast g on s.ret_gir_code=g.gir_code left join ledger_mast cl on cl.ledger_code=s.consignee_ledger_code where s.sales_code=?', 'code', 1, 0, 600031, 0),
(309, 'select s.dc_det_code dcdetcode,s.dc_code dcsalescode,s.sno,s.product_code productcode,p.product_name productname,s.packing_type_code packtypecode,pk.packing_type_name packtype,s.pack_type packingvalue,s.packs packages,s.qty totalqty,s.rate,s.amount,s.tax_per taxperc,s.tax_amt taxamt,s.tot_amt netamount,s.remarks remarks from sales sm inner join  sales_det s on s.sales_code=sm.sales_code inner join product_mast p on s.product_code=p.product_code inner join packing_type pk on pk.packing_type_code=s.packing_type_code Where sm.sales_code=?', 'code', 2, 1, 600031, 1),
(310, 'select s.ledger_code,ifnull(l.ledger_name,\'Not Available\') description,s.perc,s.amount taxamount,s.cr_dr,s.basic_ledger_code,s.basic_others,s.col_type from sales_det2 s  left join ledger_mast l on s.ledger_code=l.ledger_code where s.sales_code=?', 'code', 3, 1, 600031, 2),
(311, 'SELECT po_code code, po_no, DATE_FORMAT(po_date,\'%d/%m/%Y\'), y1.ledger_code, ledger_name, total, vat_per, vat_amt, loading_charges, freight, round_off, net_amount\nFROM yarn_po y1, ledger_mast l1\nWHERE y1.ledger_code = l1.ledger_code and y1.po_code=?', 'code', 1, 0, 600032, 0),
(312, 'select po_code code,y1.count_code,count_name,y1.mill_code,mill_name,y1.color_code,color_name,kgs,bags,cones_bag,cones,rate,y1.unit_code,unit_name,amount from yarn_po_det y1,count_mast c1,yarn_color_mast c2,mill_mast m1,unit_mast u1 where y1.count_code=c1.count_code and y1.color_code=c2.color_code and y1.mill_code=m1.mill_code and y1.unit_code=u1.unit_code and y1.po_code=?', 'code', 2, 1, 600032, 1),
(313, 'SELECT purc_code code, y1.po_code, (select po_no from yarn_po y2 where y2.po_code=y1.po_code) as po_no, bill_no, DATE_FORMAT(bill_date,\'%d/%m/%Y\'), y1.ledger_code, ledger_name, y1.total, y1.vat_per, y1.vat_amt, y1.loading_charges, y1.freight, y1.round_off, y1.net_amount\nFROM yarn_purc y1, ledger_mast l1\nWHERE y1.ledger_code = l1.ledger_code and y1.purc_code=?', 'code', 1, 0, 600033, 0),
(314, 'SELECT purc_code code, y1.count_code, count_name, y1.mill_code, mill_name, y1.color_code, color_name, kgs, bags, cones_bag, cones, rate, amount, y1.unit_code, unit_name,y1.cone_type_code,cone_type,y1.cone_weight_code,cone_weight \nFROM yarn_purc_det y1, mill_mast m1, count_mast c1, yarn_color_mast c2, yarn_po_unit u1,cone_type_mast c3,cone_weight_mast c4 \nWHERE y1.mill_code = m1.mill_code\nAND y1.count_code = c1.count_code\nAND y1.color_code = c2.color_code\nAND y1.unit_code = u1.unit_code and y1.cone_type_code=c3.cone_type_code and y1.cone_weight_code=c4.cone_weight_code and y1.purc_code=?', 'code', 2, 1, 600033, 1),
(315, 'select order_code code,order_no,DATE_FORMAT(order_date,\'%d/%m/%Y\') order_date,total_ends,s1.ledger_code,ledger_name,s1.mill_code,mill_name,s1.count_code,count_name,s1.color_code,color_name,cone_weight,no_of_cones,dis_between_flange,no_of_back_beam,no_of_creal,set_length,no_of_sized_beam,DATE_FORMAT(sized_beam_reqd_date,\'%d/%m/%Y\') sized_beam_reqd_date from sizing_set_order s1,ledger_mast l1,mill_mast m1,count_mast c1,yarn_color_mast c2 where s1.mill_code=m1.mill_code and s1.count_code=c1.count_code and s1.color_code=c2.color_code and s1.order_code=?', 'code', 1, 0, 600034, 0),
(316, 'select s1.order_code code,order_no,s1.vendor_code,vendor_name,s1.loom_type_code,loom_type,s1.width,s1.metre,s1.no_of_beams from sizing_set_order_det s1,sizing_set_order s2,vendor_mast v1,loom_type_mast l2 where s1.order_code=s2.order_code and s1.vendor_code=v1.vendor_code and s1.loom_type_code=l2.loom_type_code and s1.order_code=?', 'code', 2, 1, 600034, 1),
