(376, 'select rece_code code,DATE_FORMAT(rece_date,\'%d/%m/%Y\') as rece_date,rece_no,r1.ledger_code ledger_code,ledger_name,r1.party_code,(select ledger_name from ledger_mast l2 where l2.ledger_code=r1.party_code) party_name,(select branch from ledger_mast l2 where l2.ledger_code=r1.party_code) branch,cheque_no,DATE_FORMAT(cheque_date,\'%d/%m/%Y\') cheque_date,amount,narration,exp_ledger_code,(select ledger_name from ledger_mast l2 where l2.ledger_code=r1.exp_ledger_code) as exp_ledger_name,exp_amount, (select ledger_name from ledger_mast l2 where l2.ledger_code=r1.exp2_ledger_code) as exp2_ledger_name,exp2_amount, rece_code code from rece_mast r1,ledger_mast l1 where r1.ledger_code=l1.ledger_code and r1.rece_code=?', 'code', 1, 0, 600041, 1),
(377, 'select rece_code code,bill_no,DATE_FORMAT(bill_date,\'%d/%m/%Y\') as bill_date,tran_type,case tran_type when \'P\' then \'Purchase\' when \'S\' then \'Sales\' when \'C\' then \'Sales Return\' when \'D\' then \'Purchase Return\' when \'Z\' then \'Op. Balance\' when \'A\' then \'Advance\' end as tran_type_name,sales_amount,cgst_amount,sgst_amount,igst_amount,net_amount,already_paid_amount,balance,is_paid,discount,paid_amount from rece_det r1 where r1.rece_code=?', 'code', 2, 1, 600041, 2),
(378, 'select pay_code code,DATE_FORMAT(pay_date,\'%d/%m/%Y\') as pay_date,pay_no,r1.ledger_code ledger_code,ledger_name,r1.party_code,(select ledger_name from ledger_mast l2 where l2.ledger_code=r1.party_code) party_name,(select branch from ledger_mast l2 where l2.ledger_code=r1.party_code) branch,cheque_no,DATE_FORMAT(cheque_date,\'%d/%m/%Y\') cheque_date,amount,narration,exp_ledger_code,(select ledger_name from ledger_mast l4 where l4.ledger_code=r1.exp_ledger_code) as exp_ledger_name,exp_amount,exp2_ledger_code,(select ledger_name from ledger_mast l4 where l4.ledger_code=r1.exp2_ledger_code) as exp2_ledger_name,exp2_amount,pay_code code from pay_mast r1,ledger_mast l1 where r1.ledger_code=l1.ledger_code and r1.pay_code=?', 'code', 1, 0, 600043, 1),
(380, 'select pay_code code,bill_no,DATE_FORMAT(bill_date,\'%d/%m/%Y\') as bill_date,tran_type,case tran_type when \'P\' then \'Purchase\' when \'B\' then \'Bought Note\' when \'A\' then \'Advance\' when \'S\' then \'Sales\' when \'C\' then \'Sales Return\' when \'D\' then \'Purchase Return\' when \'Y\' then \'Op. Balance\' end as tran_type_name,sales_amount,cgst_amount,sgst_amount,igst_amount,net_amount,already_paid_amount,balance,is_paid,discount,paid_amount from pay_det r1 where r1.pay_code=?', 'code', 2, 1, 600043, 2),
(381, 'select comp_name,b1.c_code,settings_code code from bank_settings b1,company c1 where b1.c_code=c1.c_code and b1.settings_code=?', 'code', 1, 0, 600070, 0),
(382, 'select settings_code code,b1.ledger_code,ledger_name from bank_settings_det b1,ledger_mast l1 where b1.ledger_code=l1.ledger_code and b1.settings_code=?', 'code', 2, 1, 600070, 1),
(383, 'select jou_code code,jou_no,DATE_FORMAT(jou_date,\'%d/%m/%Y\') jou_date,e1.ledger_code,ledger_name,branch,amount,tran_type from journal e1,ledger_mast l1 where e1.ledger_code=l1.ledger_code and e1.jou_code=?', 'code', 1, 0, 600007, 0),
(384, 'select e1.jou_code code,e1.ledger_code credit_ledger_code,ledger_name,branch,cheque_no,e1.amount amount,(select ifnull(sum(vd_dramount-vd_cramount),0) as balance from view_vouchers v1 where v1.vd_ledger_code=e1.ledger_code and v1.vh_date<=e2.jou_date) as balance1,narration from journal_det  e1,journal e2,ledger_mast l1 where e1.jou_code=e2.jou_code and  e1.ledger_code=l1.ledger_code and e1.jou_code=?', 'code', 2, 1, 600007, 1),
(385, 'select op_code code,comp_name,o1.c_code,DATE_FORMAT(op_date,\'%d/%m/%Y\') as op_date from op_balance o1,company c1 where o1.c_code=c1.c_code and o1.op_code=?', 'code', 1, 0, 100012, 0),
(386, 'select o1.op_code code,o1.ledger_code,ledger_name,branch,debit,credit from op_balance_det o1,op_balance o2,ledger_mast l1 where o1.op_code=o2.op_code and o1.ledger_code=l1.ledger_code and o1.op_code=? order by ledger_name', 'code', 2, 1, 100012, 1),
(387, 'select jou_code code,jou_no,DATE_FORMAT(jou_date,\'%d/%m/%Y\') jou_date,e1.ledger_code,ledger_name,branch,amount,tran_type from contra e1,ledger_mast l1 where e1.ledger_code=l1.ledger_code and e1.jou_code=?', 'code', 1, 0, 600008, 0),
(388, 'select jou_code code,e1.ledger_code credit_ledger_code,ledger_name,branch,cheque_no,amount,narration from contra_det  e1,ledger_mast l1 where e1.ledger_code=l1.ledger_code and e1.jou_code=?', 'code', 2, 1, 600008, 1),
(389, 'select hsn_mast_code code,hsn_code,gst_per from hsn_mast where hsn_mast_code=?', 'code', 21, 0, 100025, 0),
(390, 'select invoice_code as code,bill_no as inv_no,DATE_FORMAT(bill_date,\'%d/%m/%Y\') as inv_date,f1.ledger_code,ledger_name,address1,address2,address3,address4,f1.gstin_no,f1.local_interstate,disc_text,f1.disc_per,discount,cgst_per,cgst_amount,sgst_per,sgst_amount,igst_per,igst_amount,courier_charges,total_amt as total_amount,f1.note as note,f1.invoice_code as code,l1.bill_disc_per as bill_disc_per,l1.aadi_disc_per as aadi_disc_per,l1.spl_disc_per as spl_disc_per,ewaybill_no,tot,l1.note as remarks,against_invoice_code,(select bill_no from f_invoice f5 where f5.invoice_code=f1.against_invoice_code) as invoice_no,DATE_FORMAT(invoice_date,\'%d/%m/%Y\') invoice_date,party_ref_no,DATE_FORMAT(party_ref_date,\'%d/%m/%Y\') party_ref_date,round_off,f1.main_ledger_code from sales_ret f1,ledger_mast l1 \r\nwhere f1.ledger_code=l1.ledger_code and f1.invoice_code=?', 'code', 1, 0, 600005, 0),
(391, 'select sno,f1.design_code as product_code,prod_code,product_name,mtrs,pcs as qty,rate,rate rate1,f1.unit_code,unit_name,amount,pcs,f1.hsn_code,disc_amt,taxable_amt  from sales_ret_det f1,product_mast p1,unit_mast u1 where f1.design_code=p1.product_code and f1.unit_code=u1.unit_code and f1.invoice_code=? order by sno', 'code', 2, 1, 600005, 1),
(392, 'select invoice_code as code,bill_no as inv_no,DATE_FORMAT(bill_date,\'%d/%m/%Y\') as inv_date,f1.ledger_code,ledger_name,address1,address2,address3,address4,f1.gstin_no,f1.local_interstate,disc_text,f1.disc_per,discount,cgst_per,cgst_amount,sgst_per,sgst_amount,igst_per,igst_amount,courier_charges,total_amt as total_amount,f1.note as note,f1.invoice_code as code,l1.bill_disc_per as bill_disc_per,l1.aadi_disc_per as aadi_disc_per,l1.spl_disc_per as spl_disc_per,ewaybill_no,tot,l1.note as remarks,against_invoice_code,(select inv_no from purc_inv f5 where f5.inv_code=f1.against_invoice_code) as invoice_no,DATE_FORMAT(invoice_date,\'%d/%m/%Y\') invoice_date,party_ref_no,DATE_FORMAT(party_ref_date,\'%d/%m/%Y\') party_ref_date,round_off from purc_ret f1,ledger_mast l1 \r\nwhere f1.ledger_code=l1.ledger_code and f1.invoice_code=?', 'code', 1, 0, 600010, 0),
(393, 'select sno,f1.design_code as product_code,prod_code,product_name,mtrs,pcs as qty,rate,f1.unit_code,unit_name,amount,pcs,f1.hsn_code,disc_amt,taxable_amt  from purc_ret_det f1,product_mast p1,unit_mast u1 where f1.design_code=p1.product_code and f1.unit_code=u1.unit_code and f1.invoice_code=? order by sno', 'code', 2, 1, 600010, 1),
(394, 'select invoice_code as code,bill_no as inv_no,DATE_FORMAT(bill_date,\'%d/%m/%Y\') as inv_date,f1.ledger_code,ledger_name,address1,address2,address3,address4,f1.gstin_no,f1.local_interstate,f1.ordered_by,t1.transport_code,t1.transport_name,paid_to_pay as freight_type,total_bales,lr_no,DATE_FORMAT(lr_date,\'%d/%m/%Y\') as lr_date,freight,weight,disc_text,f1.disc_per,discount,courier_charges,cgst_per,cgst_amount,sgst_per,sgst_amount,igst_per,igst_amount,total_amt as total_amount,f1.note as note,f1.invoice_code as code,l1.bill_disc_per as bill_disc_per,l1.aadi_disc_per as aadi_disc_per,l1.spl_disc_per as spl_disc_per,ewaybill_no,tot,l1.note as remarks from dc f1,ledger_mast l1,transport_mast t1 \r\nwhere f1.ledger_code=l1.ledger_code and f1.transport_code=t1.transport_code and f1.invoice_code=?', 'code', 1, 0, 600011, 0),
(395, 'select sno,f1.design_code as product_code,prod_code,product_name,mtrs,pcs as qty,rate,rate rate1,f1.unit_code,unit_name,amount,pcs,f1.hsn_code,disc_amt,taxable_amt  from dc_det f1,product_mast p1,unit_mast u1 where f1.design_code=p1.product_code and f1.unit_code=u1.unit_code and f1.invoice_code=? order by sno', 'code', 2, 1, 600011, 1),
(396, 'select order_code code,DATE_FORMAT(order_date,\'%d/%m/%Y\') as order_date,order_no,b1.ledger_code ledger_code,ledger_name,branch from sale_order b1,ledger_mast l1 where b1.ledger_code=l1.ledger_code and b1.order_code=?', 'code', 1, 0, 600054, 0),
(397, 'select s1.product_code product_code,prod_code,product_name,s1.unit_code unit_code,unit_name,qty,mtrs,sno from sale_order_det s1,product_mast p1,unit_mast u1 where s1.unit_code=u1.unit_code and s1.product_code=p1.product_code and s1.order_code=? order by sno', 'code', 2, 1, 600054, 1),
(398, 'select mapping_code code,DATE_FORMAT(mapping_date,\'%d/%m/%Y\') as mapping_date,mapping_no,b1.ledger_code ledger_code,ledger_name,amount,exp_ledger_code,(select ledger_name from ledger_mast l2 where l2.ledger_code=b1.exp_ledger_code) as exp_ledger_name,exp_amount,exp2_ledger_code,(select ledger_name from ledger_mast l3 where l3.ledger_code=b1.exp2_ledger_code) as exp2_ledger_name,exp2_amount,advance_type,notes  from advance_mapping b1,ledger_mast l1 where b1.ledger_code=l1.ledger_code and b1.mapping_code=?', 'code', 1, 0, 600055, 0),
(399, 'select a1.advance_code,advance_no,DATE_FORMAT(advance_date,\'%d/%m/%Y\') advance_date,adv_balance,a1.invoice_code,bill_no,DATE_FORMAT(bill_date,\'%d/%m/%Y\') bill_date,adj_amount from advance_mapping_det a1,advance a2,f_invoice f1  where a1.advance_code=a2.advance_code and a1.invoice_code=f1.invoice_code and a1.mapping_code=? ', 'code', 2, 1, 600055, 1),
(400, 'select comp_name,b1.c_code,emp_code code from emp_mast b1,company c1 where b1.c_code=c1.c_code and b1.emp_code=?', 'code', 1, 0, 100038, 0),
(401, 'select emp_code  code,emp_name,addr1,addr2,addr3,place,ph_no from emp_det where emp_code=?', 'code', 2, 1, 100038, 1),
(402, 'select comp_name,b1.c_code,stock_code code from cl_stock b1,company c1 where b1.c_code=c1.c_code and b1.stock_code=?', 'code', 1, 0, 600071, 0),
(403, 'select stock_code code,DATE_FORMAT(from_date,\'%d/%m/%Y\') from_date,DATE_FORMAT(to_date,\'%d/%m/%Y\') to_date,op_stock_value,cl_stock_value from cl_stock_det where stock_code=?', 'code', 2, 1, 600071, 1);
